func (d *durationValue) Set(v string) error {
	p, err := time.ParseDuration(v)
	if err != nil {
		return fmt.Errorf("time: invalid duration %q", v)
	}
	*d = durationValue(p)
	return nil
}
func (d *durationValue) String() string { return time.Duration(*d).String() }
func (d *durationValue) Type() string   { return "duration" }

type stringSliceValue struct {
	p       *[]string
	changed bool
}

func (s *stringSliceValue) Set(v string) error {
	vs, err := readCSV(v)
	if err != nil {
		return err
	}
	if !s.changed {
		*s.p = vs
		s.changed = true
	} else {
		*s.p = append(*s.p, vs...)
	}
	return nil
}

func (s *stringSliceValue) String() string { return "[" + strings.Join(*s.p, ",") + "]" }
func (s *stringSliceValue) Type() string   { return "stringSlice" }

// readCSV mimics pflag's comma separated parsing (quoted fields included).
func readCSV(v string) ([]string, error) {
	if v == "" {
		return []string{}, nil
	}
	var (
		out   []string
		cur   strings.Builder
		quote bool
	)
	for i := 0; i < len(v); i++ {
		switch c := v[i]; {
		case c == '"':
			quote = !quote
		case c == ',' && !quote:
			out = append(out, cur.String())
			cur.Reset()
		default:
			cur.WriteByte(c)
		}
	}
	out = append(out, cur.String())
	return out, nil
}

