package cli

import (
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
)

// Command mirrors the subset of spf13/cobra semantics that the CLI depends on.
type Command struct {
	// Use is the one-line usage, e.g. "apply [flags] [amount]".
	Use     string
	Short   string
	Long    string
	Example string
	// DisableFlagsInUseLine suppresses the automatic " [flags]" suffix.
	DisableFlagsInUseLine bool
	// Hidden keeps the command out of the parent's command list.
	Hidden bool
	// RunE is invoked with the positional arguments left after flag parsing.
	RunE func(cmd *Command, args []string) error
	// PersistentPreRunE runs before RunE, walking from the root downwards.
	PersistentPreRunE func(cmd *Command, args []string) error
	// Args validates the positional arguments.
	Args func(cmd *Command, args []string) error

	flags      *FlagSet
	pflags     *FlagSet
	parent     *Command
	commands   []*Command
	helpAdded  bool
	sortedOnce bool

	out io.Writer
	err io.Writer
}

// SetOut sets the writer used for regular output.
func (c *Command) SetOut(w io.Writer) { c.out = w }

// SetErr sets the writer used for diagnostics.
func (c *Command) SetErr(w io.Writer) { c.err = w }

// OutOrStdout returns the configured output writer.
func (c *Command) OutOrStdout() io.Writer {
	if c.out != nil {
		return c.out
	}
	if c.parent != nil {
		return c.parent.OutOrStdout()
	}
	return os.Stdout
}

// ErrOrStderr returns the configured error writer.
func (c *Command) ErrOrStderr() io.Writer {
	if c.err != nil {
		return c.err
	}
	if c.parent != nil {
		return c.parent.ErrOrStderr()
	}
	return os.Stderr
}

// Flags returns the command's own flag set.
func (c *Command) Flags() *FlagSet {
	if c.flags == nil {
		c.flags = NewFlagSet()
	}
	return c.flags
}

// PersistentFlags returns flags shared with every descendant.
func (c *Command) PersistentFlags() *FlagSet {
	if c.pflags == nil {
		c.pflags = NewFlagSet()
		c.pflags.SortFlags = true
	}
	return c.pflags
}

// AddCommand attaches sub-commands.
func (c *Command) AddCommand(cmds ...*Command) {
	for _, sub := range cmds {
		sub.parent = c
		c.commands = append(c.commands, sub)
	}
}

// Parent returns the owning command.
func (c *Command) Parent() *Command { return c.parent }

// Root walks up to the top-most command.
func (c *Command) Root() *Command {
	if c.parent != nil {
		return c.parent.Root()
	}
	return c
}

// Name is the first word of Use.
func (c *Command) Name() string {
	name := c.Use
	if i := strings.Index(name, " "); i >= 0 {
		name = name[:i]
	}
	return name
}

// CommandPath is the space separated chain of names up to the root.
func (c *Command) CommandPath() string {
	if c.parent != nil {
		return c.parent.CommandPath() + " " + c.Name()
	}
	return c.Name()
}

// Commands returns the sub-commands sorted by name.
func (c *Command) Commands() []*Command {
	if !c.sortedOnce {
		sort.SliceStable(c.commands, func(i, j int) bool { return c.commands[i].Name() < c.commands[j].Name() })
		c.sortedOnce = true
	}
	return c.commands
}

// Runnable reports whether the command has an action of its own.
func (c *Command) Runnable() bool { return c.RunE != nil }

// HasSubCommands reports whether the command groups others.
func (c *Command) HasSubCommands() bool { return len(c.commands) > 0 }

func (c *Command) hasAvailableSubCommands() bool {
	for _, sub := range c.commands {
		if !sub.Hidden {
			return true
		}
	}
	return false
}

// UseLine renders the "Usage:" first line.
func (c *Command) UseLine() string {
	var line string
	if c.parent != nil {
		line = c.parent.CommandPath() + " " + c.Use
	} else {
		line = c.Use
	}
	if c.DisableFlagsInUseLine {
		return line
	}
	if c.localFlags().Len() > 0 && !strings.Contains(line, "[flags]") {
		line += " [flags]"
	}
	return line
}

// localFlags is the union of the command flags and its own persistent flags.
func (c *Command) localFlags() *FlagSet {
	fs := NewFlagSet()
	fs.SortFlags = c.Flags().SortFlags
	if c.pflags != nil && c.flags == nil {
		fs.SortFlags = c.pflags.SortFlags
	}
	fs.addFrom(c.flags)
	fs.addFrom(c.pflags)
	return fs
}

// inheritedFlags collects persistent flags declared by the ancestors.
func (c *Command) inheritedFlags() *FlagSet {
	fs := NewFlagSet()
	fs.SortFlags = true
	for p := c.parent; p != nil; p = p.parent {
		fs.addFrom(p.pflags)
	}
	return fs
}

func (c *Command) initHelpFlag() {
	if c.helpAdded {
		return
	}
	c.helpAdded = true
	if c.Flags().Lookup("help") == nil {
		var v bool
		c.Flags().Bool(&v, "help", "h", false, "help for "+c.Name())
	}
}

// UsageString renders the command usage exactly like cobra's default template.
func (c *Command) UsageString() string {
	c.initHelpFlag()
	var b strings.Builder
	b.WriteString("Usage:")
	if c.Runnable() {
		b.WriteString("\n  " + c.UseLine())
	}
	if c.hasAvailableSubCommands() {
		b.WriteString("\n  " + c.CommandPath() + " [command]")
	}
	if c.Example != "" {
		b.WriteString("\n\nExamples:\n" + c.Example)
	}
	if c.hasAvailableSubCommands() {
		b.WriteString("\n\nAvailable Commands:")
		pad := c.commandsMaxNameLen()
		if pad < 11 {
			pad = 11
		}
		for _, sub := range c.Commands() {
			if sub.Hidden {
				continue
			}
			b.WriteString(fmt.Sprintf("\n  %-*s %s", pad, sub.Name(), sub.Short))
		}
	}
	if lf := c.localFlags(); lf.Len() > 0 {
		b.WriteString("\n\nFlags:\n" + strings.TrimRight(flagUsages(lf), " \t\n"))
	}
	if inh := c.inheritedFlags(); inh.Len() > 0 {
		b.WriteString("\n\nGlobal Flags:\n" + strings.TrimRight(flagUsages(inh), " \t\n"))
	}
	if c.hasAvailableSubCommands() {
		b.WriteString(fmt.Sprintf("\n\nUse \"%s [command] --help\" for more information about a command.", c.CommandPath()))
	}
	b.WriteString("\n")
	return b.String()
}

func (c *Command) commandsMaxNameLen() int {
	m := 0
	for _, sub := range c.commands {
		if n := len(sub.Name()); n > m {
			m = n
		}
	}
	return m
}

// HelpString renders the full help page.
func (c *Command) HelpString() string {
	var b strings.Builder
	if long := c.Long; long != "" {
		b.WriteString(strings.TrimRight(long, " \t\n") + "\n\n")
	} else if c.Short != "" {
		b.WriteString(strings.TrimRight(c.Short, " \t\n") + "\n\n")
	}
	if c.Runnable() || c.HasSubCommands() {
		b.WriteString(c.UsageString())
	}
	return b.String()
}

// Help prints the help page to stdout.
func (c *Command) Help() {
	fmt.Fprint(c.OutOrStdout(), c.HelpString())
}

// flagUsages renders the flag block the way pflag.FlagUsages does.
func flagUsages(fs *FlagSet) string {
	var (
		lines  []string
		maxlen int
	)
	fs.Visit(func(f *Flag) {
		if f.Hidden {
			return
		}
		var line string
		if f.Shorthand != "" {
			line = fmt.Sprintf("  -%s, --%s", f.Shorthand, f.Name)
		} else {
			line = fmt.Sprintf("      --%s", f.Name)
		}
		varname, usage := unquoteUsage(f)
		if varname != "" {
			line += " " + varname
		}
		if f.NoOptDefVal != "" && f.Value.Type() != "bool" {
			line += "[=" + f.NoOptDefVal + "]"
		}
		line += "\x00"
		if len(line) > maxlen {
			maxlen = len(line)
		}
		line += usage
		if !f.defaultIsZeroValue() {
			if f.Value.Type() == "string" {
				line += fmt.Sprintf(" (default %q)", f.DefValue)
			} else {
				line += fmt.Sprintf(" (default %s)", f.DefValue)
			}
		}
		lines = append(lines, line)
	})
	var b strings.Builder
	for _, line := range lines {
		i := strings.Index(line, "\x00")
		spacing := strings.Repeat(" ", maxlen-i)
		fmt.Fprintln(&b, line[:i], spacing, line[i+1:])
	}
	return b.String()
}

func unquoteUsage(f *Flag) (name, usage string) {
	usage = f.Usage
	for i := 0; i < len(usage); i++ {
		if usage[i] == '`' {
			for j := i + 1; j < len(usage); j++ {
				if usage[j] == '`' {
					name = usage[i+1 : j]
					usage = usage[:i] + name + usage[j+1:]
					return name, usage
				}
			}
			break
		}
	}
	switch name = f.Value.Type(); name {
	case "bool":
		name = ""
	case "float64":
		name = "float"
	case "int64":
		name = "int"
	case "uint64":
		name = "uint"
	case "stringSlice":
		name = "strings"
	}
	return name, usage
}

