package cmds

import (
	"fmt"

	"atlas/internal/cli"
)

// Root builds the atlas command tree.
func Root() *cli.Command {
	root := &cli.Command{
		Use:  "atlas",
		Long: "Manage your database schema as code",
	}
	root.AddCommand(
		completionCmd(),
		helpCmd(root),
		licenseCmd(),
		migrateCmd(),
		schemaCmd(),
		versionCmd(),
	)
	return root
}

func versionCmd() *cli.Command {
	return &cli.Command{
		Use:   "version",
		Short: "Prints this Atlas CLI version information.",
		RunE: func(cmd *cli.Command, _ []string) error {
			fmt.Fprint(cmd.OutOrStdout(), versionText())
			return nil
		},
	}
}

func versionText() string {
	return "atlas unofficial version - development\n" +
		"https://github.com/ariga/atlas/releases/latest\n" +
		"To download an official version, visit: https://atlasgo.io/getting-started#installation\n"
}

func licenseCmd() *cli.Command {
	return &cli.Command{
		Use:   "license",
		Short: "Display license information",
		RunE: func(cmd *cli.Command, _ []string) error {
			fmt.Fprint(cmd.OutOrStdout(), "LICENSE\nAtlas is licensed under Apache 2.0 as found in https://github.com/ariga/atlas/blob/master/LICENSE.\n")
			return nil
		},
	}
}

func helpCmd(root *cli.Command) *cli.Command {
	c := &cli.Command{
		Use:   "help [command]",
		Short: "Help about any command",
		Long: `Help provides help for any command in the application.
Simply type ` + root.Name() + ` help [path to command] for full details.`,
	}
	c.RunE = func(cmd *cli.Command, args []string) error {
		target := root
		for _, a := range args {
			next := findChild(target, a)
			if next == nil {
				fmt.Fprintf(cmd.ErrOrStderr(), "Unknown help topic %#v\n", args)
				root.Help()
				return nil
			}
			target = next
		}
		target.Help()
		return nil
	}
	return c
}

func findChild(c *cli.Command, name string) *cli.Command {
	for _, sub := range c.Commands() {
		if sub.Name() == name {
			return sub
		}
	}
	return nil
}

