// urlUsage is the shared description of database URL flags.
const (
	urlUsage    = "[driver://username:password@address/dbname?param=value] select a resource using the URL format"
	toUsage     = "[driver://username:password@address/dbname?param=value] select a desired state using the URL format"
	devURLUsage = "[driver://username:password@address/dbname?param=value] select a dev database using the URL format"
	dirUsage    = "select migration directory using URL format"
	fmtUsage    = "Go template to use to format the output"
	defaultDir  = "file://migrations"
)

// varsValue implements the repeatable --var flag.
type varsValue struct {
	vals map[string]any
}

func newVarsValue() *varsValue { return &varsValue{vals: map[string]any{}} }

func (v *varsValue) Set(s string) error {
	name, val := s, ""
	for i := 0; i < len(s); i++ {
		if s[i] == '=' {
			name, val = s[:i], s[i+1:]
			break
		}
	}
	if cur, ok := v.vals[name]; ok {
		switch c := cur.(type) {
		case []string:
			v.vals[name] = append(c, val)
		case string:
			v.vals[name] = []string{c, val}
		}
		return nil
	}
	v.vals[name] = val
	return nil
}

func (v *varsValue) String() string { return "[]" }
func (v *varsValue) Type() string   { return "<name>=<value>" }

// globalState carries the values of the shared project flags.
type globalState struct {
	configURL string
	env       string
	vars      *varsValue
}

func addGlobalFlags(c *cli.Command) *globalState {
	g := &globalState{vars: newVarsValue()}
	fs := c.PersistentFlags()
	fs.String(&g.configURL, "config", "c", "file://atlas.hcl", "select config (project) file using URL format")
	fs.String(&g.env, "env", "", "", "set which env from the config file to use")
	fs.Var(g.vars, "var", "", "input variables")
	return g
}

func lockTimeout(fs *cli.FlagSet, p *time.Duration) {
	fs.Duration(p, "lock-timeout", "", 10*time.Second, "set how long to wait for the database lock")
}

