package cli

import (
	"fmt"
	"strconv"
	"strings"
	"time"
)

// Value is the interface implemented by every flag value holder.
type Value interface {
	// Set parses the textual representation of the value.
	Set(string) error
	// String renders the value the way pflag would.
	String() string
	// Type is the name displayed in the usage line ("string", "strings", ...).
	Type() string
}

// Flag describes a single command line flag.
type Flag struct {
	Name      string
	Shorthand string
	Usage     string
	Value     Value
	// DefValue holds the textual default captured at registration time.
	DefValue string
	// NoOptDefVal is set for flags that may be given without a value (booleans).
	NoOptDefVal string
	Changed     bool
	Hidden      bool
	// Required marks flags that must be provided by the user.
	Required bool
	// annotation used by commands that accept "one of" groups.
	group string
}

func (f *Flag) defaultIsZeroValue() bool {
	switch f.Value.(type) {
	case *boolValue:
		return f.DefValue == "false"
	case *durationValue:
		// Beginning in Go 1.7, duration zero values are "0s"
		return f.DefValue == "0" || f.DefValue == "0s"
	case *intValue, *uintValue:
		return f.DefValue == "0"
	case *stringValue:
		return f.DefValue == ""
	case *stringSliceValue:
		return f.DefValue == "[]"
	default:
		switch f.Value.String() {
		case "false", "<nil>", "", "0":
			return true
		}
		return false
	}
}

// FlagSet is a small stand-in for pflag.FlagSet with the behaviours atlas relies on.
type FlagSet struct {
	flags  []*Flag
	byName map[string]*Flag
	short  map[string]*Flag
	// SortFlags reports whether usage output is sorted lexicographically.
	SortFlags bool
}

// NewFlagSet returns an empty flag set that preserves declaration order.
func NewFlagSet() *FlagSet {
	return &FlagSet{byName: map[string]*Flag{}, short: map[string]*Flag{}}
}

// AddFlag registers f.
func (fs *FlagSet) AddFlag(f *Flag) {
	if fs.byName == nil {
		fs.byName = map[string]*Flag{}
		fs.short = map[string]*Flag{}
	}
	if _, ok := fs.byName[f.Name]; ok {
		return
	}
	fs.flags = append(fs.flags, f)
	fs.byName[f.Name] = f
	if f.Shorthand != "" {
		fs.short[f.Shorthand] = f
	}
}

// Lookup returns the flag with the given name, if any.
func (fs *FlagSet) Lookup(name string) *Flag {
	if fs == nil {
		return nil
	}
	return fs.byName[name]
}

// Len reports the number of registered flags.
func (fs *FlagSet) Len() int { return len(fs.flags) }

// Visit calls fn for every flag in usage order.
func (fs *FlagSet) Visit(fn func(*Flag)) {
	for _, f := range fs.ordered() {
		fn(f)
	}
}

func (fs *FlagSet) ordered() []*Flag {
	out := make([]*Flag, len(fs.flags))
	copy(out, fs.flags)
	if fs.SortFlags {
		for i := 1; i < len(out); i++ {
			for j := i; j > 0 && out[j].Name < out[j-1].Name; j-- {
				out[j], out[j-1] = out[j-1], out[j]
			}
		}
	}
	return out
}

func (fs *FlagSet) addFrom(other *FlagSet) {
	if other == nil {
		return
	}
	for _, f := range other.flags {
		fs.AddFlag(f)
	}
}

// String registers a string flag and returns a pointer to its storage.
func (fs *FlagSet) String(p *string, name, shorthand, def, usage string) {
	*p = def
	fs.AddFlag(&Flag{Name: name, Shorthand: shorthand, Usage: usage, Value: (*stringValue)(p), DefValue: def})
}

// Bool registers a boolean flag.
func (fs *FlagSet) Bool(p *bool, name, shorthand string, def bool, usage string) {
	*p = def
	fs.AddFlag(&Flag{
		Name: name, Shorthand: shorthand, Usage: usage,
		Value: (*boolValue)(p), DefValue: strconv.FormatBool(def), NoOptDefVal: "true",
	})
}

// StringSlice registers a repeatable string flag rendered as "strings".
func (fs *FlagSet) StringSlice(p *[]string, name, shorthand string, def []string, usage string) {
	*p = def
	fs.AddFlag(&Flag{
		Name: name, Shorthand: shorthand, Usage: usage,
		Value: &stringSliceValue{p: p}, DefValue: sliceDefault(def),
	})
}

// Duration registers a time.Duration flag.
func (fs *FlagSet) Duration(p *time.Duration, name, shorthand string, def time.Duration, usage string) {
	*p = def
	fs.AddFlag(&Flag{Name: name, Shorthand: shorthand, Usage: usage, Value: (*durationValue)(p), DefValue: def.String()})
}

// Uint registers an unsigned integer flag.
func (fs *FlagSet) Uint(p *uint, name, shorthand string, def uint, usage string) {
	*p = def
	fs.AddFlag(&Flag{Name: name, Shorthand: shorthand, Usage: usage, Value: (*uintValue)(p), DefValue: strconv.FormatUint(uint64(def), 10)})
}

// Var registers a flag backed by a custom value implementation.
func (fs *FlagSet) Var(v Value, name, shorthand, usage string) {
	fs.AddFlag(&Flag{Name: name, Shorthand: shorthand, Usage: usage, Value: v, DefValue: v.String()})
}

func sliceDefault(def []string) string {
	if len(def) == 0 {
		return "[]"
	}
	return "[" + strings.Join(def, ",") + "]"
}

type stringValue string

func (s *stringValue) Set(v string) error { *s = stringValue(v); return nil }
func (s *stringValue) String() string     { return string(*s) }
func (s *stringValue) Type() string       { return "string" }

type boolValue bool

func (b *boolValue) Set(v string) error {
	p, err := strconv.ParseBool(v)
	if err != nil {
		return fmt.Errorf("strconv.ParseBool: parsing %q: invalid syntax", v)
	}
	*b = boolValue(p)
	return nil
}
func (b *boolValue) String() string { return strconv.FormatBool(bool(*b)) }
func (b *boolValue) Type() string   { return "bool" }

type intValue int

func (i *intValue) Set(v string) error {
	p, err := strconv.Atoi(v)
	if err != nil {
		return fmt.Errorf("strconv.Atoi: parsing %q: invalid syntax", v)
	}
	*i = intValue(p)
	return nil
}
