// readCSV mimics pflag's comma separated parsing (quoted fields included).
func readCSV(v string) ([]string, error) {
	if v == "" {
		return []string{}, nil
	}
	var (
		out   []string
		cur   strings.Builder
		quote bool
	)
	for i := 0; i < len(v); i++ {
		switch c := v[i]; {
		case c == '"':
			quote = !quote
		case c == ',' && !quote:
			out = append(out, cur.String())
			cur.Reset()
		default:
			cur.WriteByte(c)
		}
	}
	out = append(out, cur.String())
	return out, nil
