package hcl

import (
	"unicode/utf8"
)

func decodeRune(b []byte) (rune, int) { return utf8.DecodeRune(b) }

// scanner walks the source producing HCL native syntax tokens.
type scanner struct {
	src      []byte
	filename string
	off      int
	line     int
	col      int
	toks     Tokens
}

// Lex converts src into the token stream used by Format and Parse. Invalid
// input never fails: unrecognised bytes become TokenInvalid so that the
// formatter can still lay the file out.
func Lex(src []byte, filename string) Tokens {
	s := &scanner{src: src, filename: filename, line: 1, col: 1}
	s.scanTokens()
	return s.toks
}

func (s *scanner) pos() Pos { return Pos{Byte: s.off, Line: s.line, Col: s.col} }

func (s *scanner) advance(n int) {
	for i := 0; i < n && s.off < len(s.src); i++ {
		if s.src[s.off] == '\n' {
			s.line++
			s.col = 1
		} else {
			s.col++
		}
		s.off++
	}
}

func (s *scanner) emit(t TokenType, start Pos) {
	s.toks = append(s.toks, &Token{
		Type:  t,
		Bytes: s.src[start.Byte:s.off],
		Range: Range{Filename: s.filename, Start: start, End: s.pos()},
	})
}

func (s *scanner) peek(i int) byte {
	if s.off+i < len(s.src) {
		return s.src[s.off+i]
	}
	return 0
}

func (s *scanner) scanTokens() {
	for s.off < len(s.src) {
		c := s.src[s.off]
		switch {
		case c == ' ' || c == '\t':
			s.advance(1)
		case c == '\r' && s.peek(1) == '\n':
			start := s.pos()
			s.advance(2)
			s.emit(TokenNewline, start)
		case c == '\n':
			start := s.pos()
			s.advance(1)
			s.emit(TokenNewline, start)
		case c == '#' || (c == '/' && s.peek(1) == '/'):
			start := s.pos()
			for s.off < len(s.src) && s.src[s.off] != '\n' {
				s.advance(1)
			}
			if s.off < len(s.src) {
				s.advance(1) // single line comments swallow their newline
			}
			s.emit(TokenComment, start)
		case c == '/' && s.peek(1) == '*':
			start := s.pos()
			s.advance(2)
			for s.off < len(s.src) && !(s.src[s.off] == '*' && s.peek(1) == '/') {
				s.advance(1)
			}
			if s.off < len(s.src) {
				s.advance(2)
			}
			s.emit(TokenComment, start)
		case c == '"':
			s.scanQuoted()
		case c == '<' && s.peek(1) == '<':
			if !s.scanHeredoc() {
				s.scanOperator()
			}
		case isIdentStart(c):
			start := s.pos()
			for s.off < len(s.src) && isIdentPart(s.src[s.off]) {
				s.advance(1)
			}
			s.emit(TokenIdent, start)
		case c >= '0' && c <= '9':
			s.scanNumber()
		default:
			s.scanOperator()
		}
	}
	start := s.pos()
	s.emit(TokenEOF, start)
}

func isIdentStart(c byte) bool {
	return c == '_' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80
}

func isIdentPart(c byte) bool {
	return isIdentStart(c) || (c >= '0' && c <= '9') || c == '-'
}

func (s *scanner) scanNumber() {
	start := s.pos()
	for s.off < len(s.src) && s.src[s.off] >= '0' && s.src[s.off] <= '9' {
		s.advance(1)
	}
	if s.off < len(s.src) && s.src[s.off] == '.' && s.peek(1) >= '0' && s.peek(1) <= '9' {
		s.advance(1)
		for s.off < len(s.src) && s.src[s.off] >= '0' && s.src[s.off] <= '9' {
			s.advance(1)
		}
	}
	if s.off < len(s.src) && (s.src[s.off] == 'e' || s.src[s.off] == 'E') {
		n := 1
		if s.peek(1) == '+' || s.peek(1) == '-' {
			n = 2
		}
		if c := s.peek(n); c >= '0' && c <= '9' {
			s.advance(n)
			for s.off < len(s.src) && s.src[s.off] >= '0' && s.src[s.off] <= '9' {
				s.advance(1)
			}
		}
	}
	s.emit(TokenNumberLit, start)
}

// scanQuoted lexes a quoted template, including its interpolation sequences.
func (s *scanner) scanQuoted() {
	start := s.pos()
	s.advance(1)
	s.emit(TokenOQuote, start)
	lit := s.pos()
	flush := func() {
		if s.off > lit.Byte {
			s.emit(TokenQuotedLit, lit)
		}
	}
	for s.off < len(s.src) {
		switch c := s.src[s.off]; {
		case c == '"':
			flush()
			q := s.pos()
			s.advance(1)
			s.emit(TokenCQuote, q)
			return
		case c == '\n':
			// Unterminated string: stop before the newline.
			flush()
			return
		case c == '\\':
			s.advance(1)
			if s.off < len(s.src) {
				s.advance(1)
			}
		case (c == '$' || c == '%') && s.peek(1) == '{':
			flush()
			o := s.pos()
			s.advance(2)
			if c == '$' {
				s.emit(TokenTemplateInterp, o)
			} else {
				s.emit(TokenTemplateControl, o)
			}
			s.scanTemplateExpr()
			lit = s.pos()
		default:
			s.advance(1)
		}
	}
	flush()
}

// scanTemplateExpr lexes the tokens of a ${ ... } sequence up to its closer.
func (s *scanner) scanTemplateExpr() {
	depth := 0
	for s.off < len(s.src) {
		c := s.src[s.off]
		switch {
		case c == '}':
			if depth == 0 {
				start := s.pos()
				s.advance(1)
				s.emit(TokenTemplateSeqEnd, start)
				return
			}
			depth--
			start := s.pos()
			s.advance(1)
			s.emit(TokenCBrace, start)
		case c == '{':
			depth++
			start := s.pos()
			s.advance(1)
			s.emit(TokenOBrace, start)
		case c == '"':
			s.scanQuoted()
		case c == ' ' || c == '\t':
			s.advance(1)
		case c == '\n':
			start := s.pos()
			s.advance(1)
			s.emit(TokenNewline, start)
		case isIdentStart(c):
			start := s.pos()
			for s.off < len(s.src) && isIdentPart(s.src[s.off]) {
				s.advance(1)
			}
			s.emit(TokenIdent, start)
		case c >= '0' && c <= '9':
			s.scanNumber()
		default:
			s.scanOperator()
		}
	}
}

// scanHeredoc lexes a <<EOT / <<-EOT template. It reports false when the
// introducer is not actually a heredoc.
func (s *scanner) scanHeredoc() bool {
	i := s.off + 2
	if i < len(s.src) && s.src[i] == '-' {
		i++
	}
	j := i
	for j < len(s.src) && isIdentPart(s.src[j]) {
		j++
	}
	if j == i {
		return false
	}
	marker := string(s.src[i:j])
	k := j
	for k < len(s.src) && (s.src[k] == ' ' || s.src[k] == '\t' || s.src[k] == '\r') {
		k++
	}
	if k >= len(s.src) || s.src[k] != '\n' {
		return false
	}
	start := s.pos()
	s.advance(k + 1 - s.off)
	s.emit(TokenOHeredoc, start)
	for s.off < len(s.src) {
		lineStart := s.pos()
		trimmed := s.off
		for trimmed < len(s.src) && (s.src[trimmed] == ' ' || s.src[trimmed] == '\t') {
			trimmed++
		}
		if hasPrefixAt(s.src, trimmed, marker) {
			end := trimmed + len(marker)
			for end < len(s.src) && (s.src[end] == ' ' || s.src[end] == '\t' || s.src[end] == '\r') {
				end++
			}
			if end >= len(s.src) || s.src[end] == '\n' {
				s.advance(trimmed + len(marker) - s.off)
				s.emit(TokenCHeredoc, lineStart)
				return true
			}
		}
		for s.off < len(s.src) && s.src[s.off] != '\n' {
			s.advance(1)
		}
		if s.off < len(s.src) {
			s.advance(1)
		}
		s.emit(TokenStringLit, lineStart)
	}
	return true
}

func hasPrefixAt(src []byte, i int, p string) bool {
	if i+len(p) > len(src) {
		return false
	}
	return string(src[i:i+len(p)]) == p
}

var operators = []struct {
	text string
	typ  TokenType
}{
	{"...", TokenEllipsis},
	{"=>", TokenFatArrow},
	{"==", TokenEqualOp},
	{"!=", TokenNotEqual},
	{"<=", TokenLessThanEq},
	{">=", TokenGreaterThanEq},
	{"&&", TokenAnd},
	{"||", TokenOr},
	{"{", TokenOBrace},
	{"}", TokenCBrace},
	{"[", TokenOBrack},
	{"]", TokenCBrack},
	{"(", TokenOParen},
	{")", TokenCParen},
	{"=", TokenEqual},
	{"<", TokenLessThan},
	{">", TokenGreaterThan},
	{"!", TokenBang},
	{"+", TokenPlus},
	{"-", TokenMinus},
	{"*", TokenStar},
	{"/", TokenSlash},
	{"%", TokenPercent},
	{".", TokenDot},
	{",", TokenComma},
	{"?", TokenQuestion},
	{":", TokenColon},
}

func (s *scanner) scanOperator() {
	start := s.pos()
	for _, op := range operators {
		if hasPrefixAt(s.src, s.off, op.text) {
			s.advance(len(op.text))
			s.emit(op.typ, start)
			return
		}
	}
	_, size := decodeRune(s.src[s.off:])
	s.advance(size)
	s.emit(TokenInvalid, start)
}

