		if c := s.peek(n); c >= '0' && c <= '9' {
			s.advance(n)
			for s.off < len(s.src) && s.src[s.off] >= '0' && s.src[s.off] <= '9' {
				s.advance(1)
			}
		}
	}
	s.emit(TokenNumberLit, start)
}

// scanQuoted lexes a quoted template, including its interpolation sequences.
func (s *scanner) scanQuoted() {
	start := s.pos()
	s.advance(1)
	s.emit(TokenOQuote, start)
	lit := s.pos()
	flush := func() {
		if s.off > lit.Byte {
			s.emit(TokenQuotedLit, lit)
		}
	}
	for s.off < len(s.src) {
		switch c := s.src[s.off]; {
		case c == '"':
			flush()
			q := s.pos()
			s.advance(1)
			s.emit(TokenCQuote, q)
			return
		case c == '\n':
			// Unterminated string: stop before the newline.
			flush()
			return
		case c == '\\':
			s.advance(1)
			if s.off < len(s.src) {
				s.advance(1)
			}
		case (c == '$' || c == '%') && s.peek(1) == '{':
			flush()
			o := s.pos()
			s.advance(2)
			if c == '$' {
				s.emit(TokenTemplateInterp, o)
			} else {
				s.emit(TokenTemplateControl, o)
			}
			s.scanTemplateExpr()
			lit = s.pos()
		default:
			s.advance(1)
		}
	}
	flush()
}

// scanTemplateExpr lexes the tokens of a ${ ... } sequence up to its closer.
func (s *scanner) scanTemplateExpr() {
	depth := 0
	for s.off < len(s.src) {
		c := s.src[s.off]
		switch {
		case c == '}':
			if depth == 0 {
				start := s.pos()
				s.advance(1)
				s.emit(TokenTemplateSeqEnd, start)
				return
			}
			depth--
			start := s.pos()
			s.advance(1)
			s.emit(TokenCBrace, start)
		case c == '{':
			depth++
			start := s.pos()
			s.advance(1)
			s.emit(TokenOBrace, start)
		case c == '"':
			s.scanQuoted()
		case c == ' ' || c == '\t':
			s.advance(1)
		case c == '\n':
			start := s.pos()
			s.advance(1)
			s.emit(TokenNewline, start)
		case isIdentStart(c):
			start := s.pos()
			for s.off < len(s.src) && isIdentPart(s.src[s.off]) {
				s.advance(1)
			}
			s.emit(TokenIdent, start)
		case c >= '0' && c <= '9':
			s.scanNumber()
		default:
			s.scanOperator()
		}
	}
}

// scanHeredoc lexes a <<EOT / <<-EOT template. It reports false when the
// introducer is not actually a heredoc.
func (s *scanner) scanHeredoc() bool {
	i := s.off + 2
	if i < len(s.src) && s.src[i] == '-' {
		i++
	}
	j := i
	for j < len(s.src) && isIdentPart(s.src[j]) {
		j++
	}
	if j == i {
		return false
	}
	marker := string(s.src[i:j])
	k := j
	for k < len(s.src) && (s.src[k] == ' ' || s.src[k] == '\t' || s.src[k] == '\r') {
		k++
	}
	if k >= len(s.src) || s.src[k] != '\n' {
		return false
	}
	start := s.pos()
	s.advance(k + 1 - s.off)
	s.emit(TokenOHeredoc, start)
	for s.off < len(s.src) {
		lineStart := s.pos()
		trimmed := s.off
		for trimmed < len(s.src) && (s.src[trimmed] == ' ' || s.src[trimmed] == '\t') {
			trimmed++
		}
		if hasPrefixAt(s.src, trimmed, marker) {
			end := trimmed + len(marker)
			for end < len(s.src) && (s.src[end] == ' ' || s.src[end] == '\t' || s.src[end] == '\r') {
				end++
			}
			if end >= len(s.src) || s.src[end] == '\n' {
				s.advance(trimmed + len(marker) - s.off)
				s.emit(TokenCHeredoc, lineStart)
				return true
			}
		}
		for s.off < len(s.src) && s.src[s.off] != '\n' {
			s.advance(1)
		}
		if s.off < len(s.src) {
			s.advance(1)
		}
		s.emit(TokenStringLit, lineStart)
	}
	return true
}

func hasPrefixAt(src []byte, i int, p string) bool {
	if i+len(p) > len(src) {
		return false
	}
	return string(src[i:i+len(p)]) == p
}

var operators = []struct {
	text string
	typ  TokenType
}{
	{"...", TokenEllipsis},
	{"=>", TokenFatArrow},
	{"==", TokenEqualOp},
	{"!=", TokenNotEqual},
	{"<=", TokenLessThanEq},
	{">=", TokenGreaterThanEq},
	{"&&", TokenAnd},
	{"||", TokenOr},
	{"{", TokenOBrace},
	{"}", TokenCBrace},
	{"[", TokenOBrack},
	{"]", TokenCBrack},
	{"(", TokenOParen},
	{")", TokenCParen},
	{"=", TokenEqual},
	{"<", TokenLessThan},
	{">", TokenGreaterThan},
	{"!", TokenBang},
	{"+", TokenPlus},
	{"-", TokenMinus},
	{"*", TokenStar},
	{"/", TokenSlash},
	{"%", TokenPercent},
	{".", TokenDot},
	{",", TokenComma},
	{"?", TokenQuestion},
	{":", TokenColon},
}

func (s *scanner) scanOperator() {
	start := s.pos()
	for _, op := range operators {
		if hasPrefixAt(s.src, s.off, op.text) {
			s.advance(len(op.text))
			s.emit(op.typ, start)
			return
		}
	}
	_, size := decodeRune(s.src[s.off:])
	s.advance(size)
	s.emit(TokenInvalid, start)
}

