package hcl

import "bytes"

// Format lays out src using the canonical HCL style: two space indents per
// nesting level, single spaces between tokens and "=" signs aligned across
// consecutive attribute lines.
func Format(src []byte) []byte {
	toks := Lex(src, "")
	formatTokens(toks)
	var buf bytes.Buffer
	for _, t := range toks {
		if t.Type == TokenEOF {
			continue
		}
		for i := 0; i < t.SpacesBefore; i++ {
			buf.WriteByte(' ')
		}
		buf.Write(t.Bytes)
	}
	return buf.Bytes()
}

// formatLine splits a physical line into the cells the formatter aligns.
type formatLine struct {
	lead    Tokens
	assign  Tokens
	comment Tokens
}

func formatTokens(toks Tokens) {
	lines := linesForFormat(toks)
	formatIndent(lines)
	formatSpaces(lines)
	formatCells(lines)
}

func tokenIsNewline(t *Token) bool {
	if t.Type == TokenNewline {
		return true
	}
	return t.Type == TokenComment && len(t.Bytes) > 0 && t.Bytes[len(t.Bytes)-1] == '\n'
}

func linesForFormat(toks Tokens) []formatLine {
	if len(toks) == 0 {
		return nil
	}
	count := 1
	for _, t := range toks {
		if tokenIsNewline(t) {
			count++
		}
	}
	lines := make([]formatLine, count)
	li, start := 0, 0
	for i, t := range toks {
		if t.Type == TokenEOF {
			lines[li].lead = toks[start:i]
			start = i
			break
		}
		if tokenIsNewline(t) {
			lines[li].lead = toks[start : i+1]
			start = i + 1
			li++
		}
	}
	for i := range lines {
		line := &lines[i]
		if len(line.lead) == 0 {
			continue
		}
		if len(line.lead) > 1 && line.lead[len(line.lead)-1].Type == TokenComment {
			line.comment = line.lead[len(line.lead)-1:]
			line.lead = line.lead[:len(line.lead)-1]
		}
		for j, t := range line.lead {
			if j > 0 && t.Type == TokenEqual {
				// Only treat this as an aligned assignment when the right hand
				// side is self contained; a multi-line value must stay put.
				net := 0
				for _, rt := range line.lead[j:] {
					net += bracketChange(rt)
				}
				if net == 0 {
					line.assign = line.lead[j:]
					line.lead = line.lead[:j]
				}
				break
			}
		}
	}
	return lines
}

func formatIndent(lines []formatLine) {
	indents := make([]int, 0, 10)
	inHeredoc := false
	for i := range lines {
		line := &lines[i]
		if len(line.lead) == 0 {
			continue
		}
		if inHeredoc {
			for _, t := range line.lead {
				if t.Type == TokenCHeredoc {
					inHeredoc = false
				}
			}
			continue
		}
		if line.lead[0].Type == TokenNewline {
			line.lead[0].SpacesBefore = 0
			continue
		}
		net := 0
		for _, t := range line.lead {
			net += bracketChange(t)
			if t.Type == TokenOHeredoc {
				inHeredoc = true
			}
		}
		for _, t := range line.assign {
			net += bracketChange(t)
			if t.Type == TokenOHeredoc {
				inHeredoc = true
			}
		}
		switch {
		case net > 0:
			line.lead[0].SpacesBefore = 2 * len(indents)
			indents = append(indents, net)
		case net < 0:
			closed := -net
			for closed > 0 && len(indents) > 0 {
				last := indents[len(indents)-1]
				switch {
				case closed > last:
					closed -= last
					indents = indents[:len(indents)-1]
				case closed < last:
					indents[len(indents)-1] -= closed
					closed = 0
				default:
					indents = indents[:len(indents)-1]
					closed = 0
				}
			}
			line.lead[0].SpacesBefore = 2 * len(indents)
		default:
			line.lead[0].SpacesBefore = 2 * len(indents)
		}
	}
}

var nilToken = &Token{Type: TokenNil}

func formatSpaces(lines []formatLine) {
	for _, line := range lines {
		all := make(Tokens, 0, len(line.lead)+len(line.assign)+len(line.comment))
		all = append(all, line.lead...)
		all = append(all, line.assign...)
		all = append(all, line.comment...)
		for i, subject := range all {
			before, after := nilToken, nilToken
			if i > 0 {
				before = all[i-1]
			}
			if i < len(all)-1 {
				after = all[i+1]
			}
			if after == nilToken {
				continue
			}
			if spaceAfterToken(subject, before, after) {
				after.SpacesBefore = 1
			} else {
				after.SpacesBefore = 0
			}
		}
	}
}

func spaceAfterToken(subject, before, after *Token) bool {
	switch {
	case after.Type == TokenNewline || after.Type == TokenNil || subject.Type == TokenNil:
		return false
	case subject.Type == TokenIdent && after.Type == TokenOParen:
		// Keep a call's name attached to its argument list.
		return false
	case subject.Type == TokenDot || after.Type == TokenDot:
		return false
	case after.Type == TokenComma || after.Type == TokenEllipsis:
		return false
	case subject.Type == TokenComma:
		return true
	case subject.Type == TokenQuotedLit, subject.Type == TokenStringLit,
		subject.Type == TokenOQuote, subject.Type == TokenOHeredoc,
		after.Type == TokenQuotedLit, after.Type == TokenStringLit,
		after.Type == TokenCQuote, after.Type == TokenCHeredoc:
		// Templates are rendered verbatim.
		return false
	case subject.Type == TokenIdent && isInKeyword(subject) && before.Type == TokenIdent:
		return true
	case subject.Type == TokenMinus:
		// A minus is unary unless it follows a value.
		switch before.Type {
		case TokenNumberLit, TokenIdent, TokenCParen, TokenCBrack, TokenCBrace, TokenCQuote, TokenNil:
			return before.Type != TokenNil
		default:
			return false
		}
	case subject.Type == TokenColon && after.Type != TokenNil:
		return true
	case after.Type == TokenColon:
		return false
	case subject.Type == TokenBang:
		return false
	case bracketChange(subject) > 0:
		return false
	case bracketChange(after) < 0:
		return false
	default:
		return true
	}
}

func isInKeyword(t *Token) bool { return bytes.Equal(t.Bytes, []byte("in")) }

func formatCells(lines []formatLine) {
	chainStart, maxColumns := -1, 0
	closeAssign := func(end int) {
		for i := chainStart; i < end; i++ {
			cols := lines[i].lead.Columns()
			lines[i].assign[0].SpacesBefore = maxColumns - cols + 1
		}
		chainStart, maxColumns = -1, 0
	}
	for i, line := range lines {
		if line.assign == nil {
			if chainStart != -1 {
				closeAssign(i)
			}
			continue
		}
		if chainStart == -1 {
			chainStart = i
		}
		if cols := line.lead.Columns(); cols > maxColumns {
			maxColumns = cols
		}
	}
	if chainStart != -1 {
		closeAssign(len(lines))
	}

	chainStart, maxColumns = -1, 0
	closeComment := func(end int) {
		for i := chainStart; i < end; i++ {
			cols := lines[i].lead.Columns() + lines[i].assign.Columns()
			lines[i].comment[0].SpacesBefore = maxColumns - cols + 1
		}
		chainStart, maxColumns = -1, 0
	}
	for i, line := range lines {
		if line.comment == nil {
			if chainStart != -1 {
				closeComment(i)
			}
			continue
		}
		if chainStart == -1 {
			chainStart = i
		}
		if cols := line.lead.Columns() + line.assign.Columns(); cols > maxColumns {
			maxColumns = cols
		}
	}
	if chainStart != -1 {
		closeComment(len(lines))
	}
}

