package cmds

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"atlas/internal/cli"
	"atlas/internal/hcl"
)

// runSchemaFmt rewrites every ".hcl" file under the given paths in canonical
// layout and prints the names of the files that changed.
func runSchemaFmt(cmd *cli.Command, args []string) error {
	if len(args) == 0 {
		args = []string{"."}
	}
	for _, path := range args {
		tasks, err := tasksFor(path)
		if err != nil {
			return err
		}
		for _, task := range tasks {
			src, err := os.ReadFile(task)
			if err != nil {
				return err
			}
			out := hcl.Format(src)
			if bytes.Equal(src, out) {
				continue
			}
			fmt.Fprintln(cmd.OutOrStdout(), task)
			if err := os.WriteFile(task, out, 0644); err != nil {
				return err
			}
		}
	}
	return nil
}

// tasksFor lists the HCL files addressed by path: the file itself, or every
// ".hcl" file directly inside the directory.
func tasksFor(path string) ([]string, error) {
	info, err := os.Stat(path)
	if err != nil {
		return nil, err
	}
	if !info.IsDir() {
		return []string{path}, nil
	}
	entries, err := os.ReadDir(path)
	if err != nil {
		return nil, err
	}
	var out []string
	for _, e := range entries {
		if e.IsDir() || !strings.HasSuffix(e.Name(), ".hcl") {
			continue
		}
		if path == "." {
			out = append(out, e.Name())
		} else {
			out = append(out, filepath.Join(path, e.Name()))
		}
	}
	sort.Strings(out)
	return out, nil
}

