package hcl

import "fmt"

// Body is a sequence of attributes and blocks.
type Body struct {
	Attributes []*Attribute
	Blocks     []*Block
	SrcRange   Range
	EndRange   Range
}

// Attribute is a "name = expression" entry.
type Attribute struct {
	Name     string
	Expr     Expression
	Range    Range
	NameRange Range
}

// Block is a labelled body, e.g. `table "users" { ... }`.
type Block struct {
	Type        string
	Labels      []string
	Body        *Body
	TypeRange   Range
	LabelRanges []Range
	DefRange    Range
}

// Expression is any HCL expression node.
type Expression interface {
	exprRange() Range
}

// LiteralExpr holds a number or boolean or null constant.
type LiteralExpr struct {
	Val Value
	Rng Range
}

func (e *LiteralExpr) exprRange() Range { return e.Rng }

// TemplateExpr is a quoted string with zero or more interpolations.
type TemplateExpr struct {
	Parts []Expression
	Rng   Range
	// Quoted reports whether the template came from a "..." literal.
	Quoted bool
}

func (e *TemplateExpr) exprRange() Range { return e.Rng }

// StringExpr is a constant piece of a template.
type StringExpr struct {
	Val string
	Rng Range
}

func (e *StringExpr) exprRange() Range { return e.Rng }

// Traversal is a dotted reference such as `var.name` or `table.users.column.id`.
type Traversal struct {
	Steps []Step
	Rng   Range
}

func (e *Traversal) exprRange() Range { return e.Rng }

// Step is a single element of a traversal.
type Step struct {
	Name  string
	Index Expression // non-nil for [..] steps
}

// CallExpr is a function call.
type CallExpr struct {
	Name string
	Args []Expression
	Rng  Range
}

func (e *CallExpr) exprRange() Range { return e.Rng }

// TupleExpr is a [..] list constructor.
type TupleExpr struct {
	Items []Expression
	Rng   Range
}

func (e *TupleExpr) exprRange() Range { return e.Rng }

// ObjectExpr is a { .. } object constructor.
type ObjectExpr struct {
	Items []ObjectItem
	Rng   Range
}

// ObjectItem is one key/value pair of an object constructor.
type ObjectItem struct {
	Key   Expression
	Value Expression
}

func (e *ObjectExpr) exprRange() Range { return e.Rng }

// IndexExpr is `coll[key]`.
type IndexExpr struct {
	Coll Expression
	Key  Expression
	Rng  Range
}

func (e *IndexExpr) exprRange() Range { return e.Rng }

// BinaryExpr is an infix operation.
type BinaryExpr struct {
	Op   string
	L, R Expression
	Rng  Range
}

func (e *BinaryExpr) exprRange() Range { return e.Rng }

// UnaryExpr is a prefix operation.
type UnaryExpr struct {
	Op  string
	Val Expression
	Rng Range
}

func (e *UnaryExpr) exprRange() Range { return e.Rng }

// CondExpr is `cond ? a : b`.
type CondExpr struct {
	Cond, True, False Expression
	Rng               Range
}

func (e *CondExpr) exprRange() Range { return e.Rng }

// Diagnostic reports a problem found while parsing or evaluating.
type Diagnostic struct {
	Summary string
	Detail  string
	Subject Range
}

func (d *Diagnostic) Error() string {
	return fmt.Sprintf("%s:%d,%d-%d: %s; %s",
		d.Subject.Filename, d.Subject.Start.Line, d.Subject.Start.Col, d.Subject.End.Col,
		d.Summary, d.Detail)
}

// Diagnostics is a list of problems; the first one is reported to the user.
type Diagnostics []*Diagnostic

func (ds Diagnostics) Error() string {
	if len(ds) == 0 {
		return "no diagnostics"
	}
	return ds[0].Error()
}

// HasErrors reports whether any diagnostic was collected.
func (ds Diagnostics) HasErrors() bool { return len(ds) > 0 }

