package hcl

import (
	"strconv"
	"strings"
)

// parser turns a token stream into a Body.
type parser struct {
	toks Tokens
	i    int
	file string
	dgs  Diagnostics
}

// Parse reads a complete HCL native syntax file.
func Parse(src []byte, filename string) (*Body, Diagnostics) {
	toks := filterComments(Lex(src, filename))
	p := &parser{toks: toks, file: filename}
	body := p.parseBody(false)
	return body, p.dgs
}

func filterComments(in Tokens) Tokens {
	out := make(Tokens, 0, len(in))
	for _, t := range in {
		if t.Type != TokenComment {
			out = append(out, t)
			continue
		}
		// A single line comment terminates its line.
		if len(t.Bytes) > 0 && t.Bytes[len(t.Bytes)-1] == '\n' {
			out = append(out, &Token{Type: TokenNewline, Bytes: []byte("\n"), Range: t.Range})
		}
	}
	return out
}

func (p *parser) peek() *Token {
	if p.i < len(p.toks) {
		return p.toks[p.i]
	}
	return p.toks[len(p.toks)-1]
}

func (p *parser) next() *Token {
	t := p.peek()
	if p.i < len(p.toks)-1 {
		p.i++
	}
	return t
}

func (p *parser) errf(rng Range, summary, detail string) {
	p.dgs = append(p.dgs, &Diagnostic{Summary: summary, Detail: detail, Subject: rng})
}

func (p *parser) skipNewlines() {
	for p.peek().Type == TokenNewline {
		p.next()
	}
}

// parseBody reads attributes and blocks until "}" (when nested) or EOF.
func (p *parser) parseBody(nested bool) *Body {
	body := &Body{}
	start := p.peek().Range
	body.SrcRange = start
	for {
		p.skipNewlines()
		t := p.peek()
		switch t.Type {
		case TokenEOF:
			body.EndRange = t.Range
			if nested {
				p.errf(t.Range, "Unclosed configuration block", "There is no closing brace for this block before the end of the file.")
			}
			return body
		case TokenCBrace:
			if nested {
				body.EndRange = t.Range
				p.next()
				return body
			}
			p.errf(t.Range, "Argument or block definition required", "An argument or block definition is required here.")
			p.recoverLine()
			continue
		case TokenIdent:
			if !p.parseBodyItem(body) {
				p.recoverLine()
			}
		default:
			p.errf(t.Range, "Argument or block definition required", "An argument or block definition is required here.")
			p.recoverLine()
		}
		if len(p.dgs) > 0 {
			// Stop at the first problem; the caller reports it verbatim.
			return body
		}
	}
}

// parseBodyItem parses one attribute or block. It reports false on error.
func (p *parser) parseBodyItem(body *Body) bool {
	name := p.next()
	switch t := p.peek(); t.Type {
	case TokenEqual:
		p.next()
		expr := p.parseExpression()
		body.Attributes = append(body.Attributes, &Attribute{
			Name:      string(name.Bytes),
			Expr:      expr,
			Range:     Range{Filename: p.file, Start: name.Range.Start, End: p.peek().Range.Start},
			NameRange: name.Range,
		})
		return p.endOfLine()
	case TokenOQuote, TokenIdent, TokenOBrace:
		blk := &Block{Type: string(name.Bytes), TypeRange: name.Range, DefRange: name.Range}
		for {
			switch l := p.peek(); l.Type {
			case TokenOQuote:
				s, ok := p.parseQuotedLiteral()
				if !ok {
					return false
				}
				blk.Labels = append(blk.Labels, s)
				blk.LabelRanges = append(blk.LabelRanges, l.Range)
			case TokenIdent:
				p.next()
				blk.Labels = append(blk.Labels, string(l.Bytes))
				blk.LabelRanges = append(blk.LabelRanges, l.Range)
			case TokenOBrace:
				p.next()
				blk.Body = p.parseBody(true)
				body.Blocks = append(body.Blocks, blk)
				return true
			default:
				p.errf(l.Range, "Invalid block definition", "Either a quoted string block label or an opening brace (\"{\") is expected here.")
				return false
			}
		}
	default:
		p.errf(t.Range, "Argument or block definition required", "An argument or block definition is required here.")
		return false
	}
}

func (p *parser) endOfLine() bool {
	switch t := p.peek(); t.Type {
	case TokenNewline, TokenEOF, TokenCBrace:
		return true
	default:
		p.errf(t.Range, "Missing newline after argument", "An argument definition must end with a newline.")
		return false
	}
}

func (p *parser) recoverLine() {
	for {
		switch p.peek().Type {
		case TokenEOF:
			return
		case TokenNewline:
			p.next()
			return
		default:
			p.next()
		}
	}
}

// parseQuotedLiteral reads a "..." with no interpolations.
func (p *parser) parseQuotedLiteral() (string, bool) {
	expr := p.parseTemplate()
	tmpl, ok := expr.(*TemplateExpr)
	if !ok {
		return "", false
	}
	var b strings.Builder
	for _, part := range tmpl.Parts {
		s, ok := part.(*StringExpr)
		if !ok {
			p.errf(tmpl.Rng, "Invalid string literal", "A literal string is required here.")
			return "", false
		}
		b.WriteString(s.Val)
	}
	return b.String(), true
}

func (p *parser) parseTemplate() Expression {
	open := p.next() // consume the opening quote
	tmpl := &TemplateExpr{Rng: open.Range, Quoted: true}
	for {
		switch t := p.peek(); t.Type {
		case TokenCQuote:
			p.next()
			tmpl.Rng.End = t.Range.End
			return tmpl
		case TokenQuotedLit:
			p.next()
			tmpl.Parts = append(tmpl.Parts, &StringExpr{Val: unescape(string(t.Bytes)), Rng: t.Range})
		case TokenTemplateInterp:
			p.next()
			tmpl.Parts = append(tmpl.Parts, p.parseExpression())
			if p.peek().Type == TokenTemplateSeqEnd {
				p.next()
			}
		case TokenTemplateControl:
			p.next()
			// Directives are not supported; skip to the closing sequence.
			for p.peek().Type != TokenTemplateSeqEnd && p.peek().Type != TokenEOF {
				p.next()
			}
			p.next()
		case TokenEOF:
			p.errf(t.Range, "Unterminated template string", "No closing marker was found for the string.")
			return tmpl
		default:
			p.next()
		}
	}
}

func unescape(s string) string {
	if !strings.ContainsRune(s, '\\') {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] != '\\' || i+1 >= len(s) {
			b.WriteByte(s[i])
			continue
		}
		i++
		switch s[i] {
		case 'n':
			b.WriteByte('\n')
		case 'r':
			b.WriteByte('\r')
		case 't':
			b.WriteByte('\t')
		case '"':
			b.WriteByte('"')
		case '\\':
			b.WriteByte('\\')
		case 'u':
			if i+4 < len(s) {
				if v, err := strconv.ParseUint(s[i+1:i+5], 16, 32); err == nil {
					b.WriteRune(rune(v))
					i += 4
					continue
				}
			}
			b.WriteByte(s[i])
		default:
			b.WriteByte('\\')
			b.WriteByte(s[i])
		}
	}
	return b.String()
}

// parseExpression parses a full expression including conditionals.
func (p *parser) parseExpression() Expression {
	cond := p.parseBinary(0)
	if p.peek().Type != TokenQuestion {
		return cond
	}
	p.next()
	yes := p.parseExpression()
	if p.peek().Type == TokenColon {
		p.next()
	}
	no := p.parseExpression()
	return &CondExpr{Cond: cond, True: yes, False: no, Rng: cond.exprRange()}
}

var precedence = map[TokenType]int{
	TokenOr:            1,
	TokenAnd:           2,
	TokenEqualOp:       3,
	TokenNotEqual:      3,
	TokenLessThan:      4,
	TokenLessThanEq:    4,
	TokenGreaterThan:   4,
	TokenGreaterThanEq: 4,
	TokenPlus:          5,
	TokenMinus:         5,
	TokenStar:          6,
	TokenSlash:         6,
	TokenPercent:       6,
}

func (p *parser) parseBinary(min int) Expression {
	left := p.parseUnary()
	for {
		t := p.peek()
		prec, ok := precedence[t.Type]
		if !ok || prec < min {
			return left
		}
		p.next()
		right := p.parseBinary(prec + 1)
		left = &BinaryExpr{Op: string(t.Bytes), L: left, R: right, Rng: left.exprRange()}
	}
}

func (p *parser) parseUnary() Expression {
	switch t := p.peek(); t.Type {
	case TokenMinus, TokenBang:
		p.next()
		return &UnaryExpr{Op: string(t.Bytes), Val: p.parseUnary(), Rng: t.Range}
	}
	return p.parsePostfix()
}

func (p *parser) parsePostfix() Expression {
	e := p.parsePrimary()
	for {
		switch p.peek().Type {
		case TokenDot:
			p.next()
			t := p.peek()
			if t.Type != TokenIdent && t.Type != TokenNumberLit && t.Type != TokenStar {
				p.errf(t.Range, "Invalid attribute name", "An attribute name is required after a dot.")
				return e
			}
			p.next()
			if tr, ok := e.(*Traversal); ok {
				tr.Steps = append(tr.Steps, Step{Name: string(t.Bytes)})
				tr.Rng.End = t.Range.End
				continue
			}
			e = &IndexExpr{Coll: e, Key: &LiteralExpr{Val: StringVal(string(t.Bytes))}, Rng: e.exprRange()}
		case TokenOBrack:
			p.next()
			key := p.parseExpression()
			if p.peek().Type == TokenCBrack {
				p.next()
			}
			e = &IndexExpr{Coll: e, Key: key, Rng: e.exprRange()}
		default:
			return e
		}
	}
}

func (p *parser) parsePrimary() Expression {
	t := p.peek()
	switch t.Type {
	case TokenOQuote:
		return p.parseTemplate()
	case TokenOHeredoc:
		return p.parseHeredoc()
	case TokenNumberLit:
		p.next()
		f, _ := strconv.ParseFloat(string(t.Bytes), 64)
		return &LiteralExpr{Val: NumberVal(f, string(t.Bytes)), Rng: t.Range}
	case TokenIdent:
		name := string(t.Bytes)
		switch name {
		case "true", "false":
			p.next()
			return &LiteralExpr{Val: BoolVal(name == "true"), Rng: t.Range}
		case "null":
			p.next()
			return &LiteralExpr{Val: NullVal(), Rng: t.Range}
		}
		p.next()
		if p.peek().Type == TokenOParen {
			p.next()
			call := &CallExpr{Name: name, Rng: t.Range}
			for {
				p.skipNewlines()
				if p.peek().Type == TokenCParen {
					p.next()
					return call
				}
				if p.peek().Type == TokenEOF {
					p.errf(p.peek().Range, "Unclosed function call", "There is no closing parenthesis for this function call.")
					return call
				}
				call.Args = append(call.Args, p.parseExpression())
				p.skipNewlines()
				if p.peek().Type == TokenComma {
					p.next()
				}
			}
		}
		return &Traversal{Steps: []Step{{Name: name}}, Rng: t.Range}
	case TokenOParen:
		p.next()
		e := p.parseExpression()
		if p.peek().Type == TokenCParen {
			p.next()
		}
		return e
	case TokenOBrack:
		p.next()
		tup := &TupleExpr{Rng: t.Range}
		for {
			p.skipNewlines()
			if p.peek().Type == TokenCBrack {
				p.next()
				return tup
			}
			if p.peek().Type == TokenEOF {
				p.errf(p.peek().Range, "Unclosed tuple constructor", "There is no corresponding closing bracket.")
				return tup
			}
			tup.Items = append(tup.Items, p.parseExpression())
			p.skipNewlines()
			if p.peek().Type == TokenComma {
				p.next()
			}
		}
	case TokenOBrace:
		p.next()
		obj := &ObjectExpr{Rng: t.Range}
		for {
			p.skipNewlines()
			if p.peek().Type == TokenCBrace {
				p.next()
				return obj
			}
			if p.peek().Type == TokenEOF {
				p.errf(p.peek().Range, "Unclosed object constructor", "There is no corresponding closing brace.")
				return obj
			}
			key := p.parseExpression()
			if p.peek().Type == TokenColon || p.peek().Type == TokenEqual {
				p.next()
			}
			obj.Items = append(obj.Items, ObjectItem{Key: key, Value: p.parseExpression()})
			p.skipNewlines()
			if p.peek().Type == TokenComma {
				p.next()
			}
		}
	default:
		p.errf(t.Range, "Invalid expression", "Expected the start of an expression, but found an invalid expression token.")
		p.next()
		return &LiteralExpr{Val: NullVal(), Rng: t.Range}
	}
}

func (p *parser) parseHeredoc() Expression {
	open := p.next()
	tmpl := &TemplateExpr{Rng: open.Range}
	indented := strings.HasPrefix(string(open.Bytes), "<<-")
	var lines []string
	for {
		t := p.peek()
		switch t.Type {
		case TokenStringLit:
			p.next()
			lines = append(lines, string(t.Bytes))
		case TokenCHeredoc:
			p.next()
			tmpl.Parts = append(tmpl.Parts, &StringExpr{Val: joinHeredoc(lines, indented), Rng: open.Range})
			return tmpl
		default:
			tmpl.Parts = append(tmpl.Parts, &StringExpr{Val: joinHeredoc(lines, indented), Rng: open.Range})
			return tmpl
		}
	}
}

func joinHeredoc(lines []string, indented bool) string {
	if !indented || len(lines) == 0 {
		return strings.Join(lines, "")
	}
	prefix := -1
	for _, l := range lines {
		n := len(l) - len(strings.TrimLeft(l, " \t"))
		if prefix == -1 || n < prefix {
			prefix = n
		}
	}
	out := make([]string, len(lines))
	for i, l := range lines {
		out[i] = l[prefix:]
	}
	return strings.Join(out, "")
}

