package hcl

import (
	"strconv"
	"strings"
)

// parser turns a token stream into a Body.
type parser struct {
	toks Tokens
	i    int
	file string
	dgs  Diagnostics
}

// Parse reads a complete HCL native syntax file.
func Parse(src []byte, filename string) (*Body, Diagnostics) {
	toks := filterComments(Lex(src, filename))
	p := &parser{toks: toks, file: filename}
	body := p.parseBody(false)
	return body, p.dgs
}

func filterComments(in Tokens) Tokens {
	out := make(Tokens, 0, len(in))
	for _, t := range in {
		if t.Type != TokenComment {
			out = append(out, t)
			continue
		}
		// A single line comment terminates its line.
		if len(t.Bytes) > 0 && t.Bytes[len(t.Bytes)-1] == '\n' {
			out = append(out, &Token{Type: TokenNewline, Bytes: []byte("\n"), Range: t.Range})
		}
	}
	return out
}

func (p *parser) peek() *Token {
	if p.i < len(p.toks) {
		return p.toks[p.i]
	}
	return p.toks[len(p.toks)-1]
}

func (p *parser) next() *Token {
	t := p.peek()
	if p.i < len(p.toks)-1 {
		p.i++
	}
	return t
}

func (p *parser) errf(rng Range, summary, detail string) {
	p.dgs = append(p.dgs, &Diagnostic{Summary: summary, Detail: detail, Subject: rng})
}

func (p *parser) skipNewlines() {
	for p.peek().Type == TokenNewline {
		p.next()
	}
}

// parseBody reads attributes and blocks until "}" (when nested) or EOF.
func (p *parser) parseBody(nested bool) *Body {
	body := &Body{}
	start := p.peek().Range
	body.SrcRange = start
	for {
		p.skipNewlines()
		t := p.peek()
		switch t.Type {
		case TokenEOF:
			body.EndRange = t.Range
			if nested {
				p.errf(t.Range, "Unclosed configuration block", "There is no closing brace for this block before the end of the file.")
			}
			return body
		case TokenCBrace:
			if nested {
				body.EndRange = t.Range
				p.next()
				return body
			}
			p.errf(t.Range, "Argument or block definition required", "An argument or block definition is required here.")
			p.recoverLine()
			continue
		case TokenIdent:
			if !p.parseBodyItem(body) {
				p.recoverLine()
			}
		default:
			p.errf(t.Range, "Argument or block definition required", "An argument or block definition is required here.")
			p.recoverLine()
		}
		if len(p.dgs) > 0 {
			// Stop at the first problem; the caller reports it verbatim.
			return body
		}
	}
}

// parseBodyItem parses one attribute or block. It reports false on error.
func (p *parser) parseBodyItem(body *Body) bool {
	name := p.next()
	switch t := p.peek(); t.Type {
	case TokenEqual:
		p.next()
		expr := p.parseExpression()
		body.Attributes = append(body.Attributes, &Attribute{
			Name:      string(name.Bytes),
			Expr:      expr,
			Range:     Range{Filename: p.file, Start: name.Range.Start, End: p.peek().Range.Start},
			NameRange: name.Range,
		})
		return p.endOfLine()
	case TokenOQuote, TokenIdent, TokenOBrace:
		blk := &Block{Type: string(name.Bytes), TypeRange: name.Range, DefRange: name.Range}
		for {
			switch l := p.peek(); l.Type {
			case TokenOQuote:
				s, ok := p.parseQuotedLiteral()
				if !ok {
					return false
				}
				blk.Labels = append(blk.Labels, s)
				blk.LabelRanges = append(blk.LabelRanges, l.Range)
			case TokenIdent:
				p.next()
				blk.Labels = append(blk.Labels, string(l.Bytes))
				blk.LabelRanges = append(blk.LabelRanges, l.Range)
			case TokenOBrace:
				p.next()
				blk.Body = p.parseBody(true)
				body.Blocks = append(body.Blocks, blk)
				return true
			default:
				p.errf(l.Range, "Invalid block definition", "Either a quoted string block label or an opening brace (\"{\") is expected here.")
				return false
			}
		}
	default:
		p.errf(t.Range, "Argument or block definition required", "An argument or block definition is required here.")
		return false
	}
}

func (p *parser) endOfLine() bool {
	switch t := p.peek(); t.Type {
	case TokenNewline, TokenEOF, TokenCBrace:
		return true
	default:
		p.errf(t.Range, "Missing newline after argument", "An argument definition must end with a newline.")
		return false
	}
}

func (p *parser) recoverLine() {
	for {
		switch p.peek().Type {
		case TokenEOF:
			return
		case TokenNewline:
			p.next()
			return
		default:
			p.next()
		}
	}
}

// parseQuotedLiteral reads a "..." with no interpolations.
func (p *parser) parseQuotedLiteral() (string, bool) {
	expr := p.parseTemplate()
	tmpl, ok := expr.(*TemplateExpr)
	if !ok {
		return "", false
