	var b strings.Builder
	for _, part := range tmpl.Parts {
		s, ok := part.(*StringExpr)
		if !ok {
			p.errf(tmpl.Rng, "Invalid string literal", "A literal string is required here.")
			return "", false
		}
		b.WriteString(s.Val)
	}
	return b.String(), true
}

func (p *parser) parseTemplate() Expression {
	open := p.next() // consume the opening quote
	tmpl := &TemplateExpr{Rng: open.Range, Quoted: true}
	for {
