package hcl

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// Kind enumerates the dynamic types a Value can hold.
type Kind int

// The supported value kinds.
const (
	KindNull Kind = iota
	KindBool
	KindNumber
	KindString
	KindTuple
	KindObject
)

// Value is a dynamically typed HCL value.
type Value struct {
	Kind    Kind
	Bool    bool
	Num     float64
	NumText string
	Str     string
	Tuple   []Value
	Obj     map[string]Value
	Keys    []string
}

// NullVal returns the null value.
func NullVal() Value { return Value{Kind: KindNull} }

// BoolVal wraps a boolean.
func BoolVal(b bool) Value { return Value{Kind: KindBool, Bool: b} }

// StringVal wraps a string.
func StringVal(s string) Value { return Value{Kind: KindString, Str: s} }

// NumberVal wraps a number, remembering how it was written.
func NumberVal(f float64, text string) Value {
	if text == "" {
		text = formatFloat(f)
	}
	return Value{Kind: KindNumber, Num: f, NumText: text}
}

// TupleVal wraps a list of values.
func TupleVal(vs []Value) Value { return Value{Kind: KindTuple, Tuple: vs} }

// ObjectVal wraps a map, preserving key order for rendering.
func ObjectVal(m map[string]Value, keys []string) Value {
	if keys == nil {
		keys = make([]string, 0, len(m))
		for k := range m {
			keys = append(keys, k)
		}
		sort.Strings(keys)
	}
	return Value{Kind: KindObject, Obj: m, Keys: keys}
}

func formatFloat(f float64) string { return strconv.FormatFloat(f, 'f', -1, 64) }

// IsNull reports whether the value is null.
func (v Value) IsNull() bool { return v.Kind == KindNull }

// AsString renders the value the way HCL would inside a template.
func (v Value) AsString() string {
	switch v.Kind {
	case KindString:
		return v.Str
	case KindBool:
		if v.Bool {
			return "true"
		}
		return "false"
	case KindNumber:
		return v.NumText
	case KindNull:
		return ""
	default:
		return v.GoString()
	}
}

// GoString renders a debug representation.
func (v Value) GoString() string {
	switch v.Kind {
	case KindTuple:
		parts := make([]string, len(v.Tuple))
		for i, e := range v.Tuple {
			parts[i] = e.GoString()
		}
		return "[" + strings.Join(parts, ", ") + "]"
	case KindObject:
		parts := make([]string, 0, len(v.Keys))
		for _, k := range v.Keys {
			parts = append(parts, fmt.Sprintf("%s = %s", k, v.Obj[k].GoString()))
		}
		return "{" + strings.Join(parts, ", ") + "}"
	case KindString:
		return strconv.Quote(v.Str)
	default:
		return v.AsString()
	}
}

// Truthy reports the value's boolean interpretation.
func (v Value) Truthy() bool {
	switch v.Kind {
	case KindBool:
		return v.Bool
	case KindNumber:
		return v.Num != 0
	case KindString:
		return v.Str != ""
	case KindNull:
		return false
	default:
		return true
	}
}

// Equal reports deep equality.
func (v Value) Equal(o Value) bool {
	if v.Kind != o.Kind {
		return false
	}
	switch v.Kind {
	case KindNull:
		return true
	case KindBool:
		return v.Bool == o.Bool
	case KindNumber:
		return v.Num == o.Num
	case KindString:
		return v.Str == o.Str
	case KindTuple:
		if len(v.Tuple) != len(o.Tuple) {
			return false
		}
		for i := range v.Tuple {
			if !v.Tuple[i].Equal(o.Tuple[i]) {
				return false
			}
		}
		return true
	default:
		if len(v.Obj) != len(o.Obj) {
			return false
		}
		for k, a := range v.Obj {
			b, ok := o.Obj[k]
			if !ok || !a.Equal(b) {
				return false
			}
		}
		return true
	}
}

