package hcl

import (
	"fmt"
	"strings"
)

// EvalContext provides the variables and functions visible to an expression.
type EvalContext struct {
	Variables map[string]Value
	Functions map[string]Function
	Parent    *EvalContext
}

// Function is a callable exposed to HCL expressions.
type Function func(args []Value) (Value, error)

// NewChild returns a context that inherits from c.
func (c *EvalContext) NewChild() *EvalContext {
	return &EvalContext{Variables: map[string]Value{}, Functions: map[string]Function{}, Parent: c}
}

func (c *EvalContext) lookupVar(name string) (Value, bool) {
	for ctx := c; ctx != nil; ctx = ctx.Parent {
		if v, ok := ctx.Variables[name]; ok {
			return v, true
		}
	}
	return Value{}, false
}

func (c *EvalContext) lookupFunc(name string) (Function, bool) {
	for ctx := c; ctx != nil; ctx = ctx.Parent {
		if f, ok := ctx.Functions[name]; ok {
			return f, true
		}
	}
	return nil, false
}

// Eval reduces the expression to a value.
func Eval(e Expression, ctx *EvalContext) (Value, Diagnostics) {
	var dgs Diagnostics
	v := evalExpr(e, ctx, &dgs)
	return v, dgs
}

func evalExpr(e Expression, ctx *EvalContext, dgs *Diagnostics) Value {
	switch e := e.(type) {
	case *LiteralExpr:
		return e.Val
	case *StringExpr:
		return StringVal(e.Val)
	case *TemplateExpr:
		if len(e.Parts) == 1 {
			if s, ok := e.Parts[0].(*StringExpr); ok {
				return StringVal(s.Val)
			}
		}
		if len(e.Parts) == 0 {
			return StringVal("")
		}
		var b strings.Builder
		for _, part := range e.Parts {
			b.WriteString(evalExpr(part, ctx, dgs).AsString())
		}
		return StringVal(b.String())
	case *Traversal:
		return evalTraversal(e, ctx, dgs)
	case *CallExpr:
		fn, ok := ctx.lookupFunc(e.Name)
		if !ok {
			*dgs = append(*dgs, &Diagnostic{
				Summary: "Call to unknown function",
				Detail:  fmt.Sprintf("There is no function named %q.", e.Name),
				Subject: e.Rng,
			})
			return NullVal()
		}
		args := make([]Value, len(e.Args))
		for i, a := range e.Args {
			args[i] = evalExpr(a, ctx, dgs)
		}
		v, err := fn(args)
		if err != nil {
			*dgs = append(*dgs, &Diagnostic{
				Summary: "Error in function call",
				Detail:  fmt.Sprintf("Call to function %q failed: %v.", e.Name, err),
				Subject: e.Rng,
			})
			return NullVal()
		}
		return v
	case *TupleExpr:
		vs := make([]Value, len(e.Items))
		for i, it := range e.Items {
			vs[i] = evalExpr(it, ctx, dgs)
		}
		return TupleVal(vs)
	case *ObjectExpr:
		m := map[string]Value{}
		keys := make([]string, 0, len(e.Items))
		for _, it := range e.Items {
			k := objectKey(it.Key, ctx, dgs)
			if _, dup := m[k]; !dup {
				keys = append(keys, k)
			}
			m[k] = evalExpr(it.Value, ctx, dgs)
		}
		return ObjectVal(m, keys)
	case *IndexExpr:
		coll := evalExpr(e.Coll, ctx, dgs)
		key := evalExpr(e.Key, ctx, dgs)
		return index(coll, key, e.Rng, dgs)
	case *UnaryExpr:
		v := evalExpr(e.Val, ctx, dgs)
		switch e.Op {
		case "-":
			return NumberVal(-v.Num, "")
		case "!":
			return BoolVal(!v.Truthy())
		}
		return v
	case *BinaryExpr:
		return evalBinary(e, ctx, dgs)
	case *CondExpr:
		if evalExpr(e.Cond, ctx, dgs).Truthy() {
			return evalExpr(e.True, ctx, dgs)
		}
		return evalExpr(e.False, ctx, dgs)
	default:
		return NullVal()
	}
}

func objectKey(e Expression, ctx *EvalContext, dgs *Diagnostics) string {
	if tr, ok := e.(*Traversal); ok && len(tr.Steps) == 1 {
		return tr.Steps[0].Name
	}
	return evalExpr(e, ctx, dgs).AsString()
}

func evalTraversal(t *Traversal, ctx *EvalContext, dgs *Diagnostics) Value {
	root := t.Steps[0].Name
	v, ok := ctx.lookupVar(root)
	if !ok {
		*dgs = append(*dgs, &Diagnostic{
			Summary: "Unknown variable",
			Detail:  fmt.Sprintf("There is no variable named %q.", root),
			Subject: t.Rng,
		})
		return NullVal()
	}
	for _, step := range t.Steps[1:] {
		v = index(v, StringVal(step.Name), t.Rng, dgs)
	}
	return v
}

func index(coll, key Value, rng Range, dgs *Diagnostics) Value {
	switch coll.Kind {
	case KindObject:
		v, ok := coll.Obj[key.AsString()]
		if !ok {
			*dgs = append(*dgs, &Diagnostic{
				Summary: "Unsupported attribute",
				Detail:  fmt.Sprintf("This object does not have an attribute named %q.", key.AsString()),
				Subject: rng,
			})
			return NullVal()
		}
		return v
	case KindTuple:
		i := int(key.Num)
		if key.Kind != KindNumber || i < 0 || i >= len(coll.Tuple) {
			*dgs = append(*dgs, &Diagnostic{
				Summary: "Invalid index",
				Detail:  "The given key does not identify an element in this collection value.",
				Subject: rng,
			})
			return NullVal()
		}
		return coll.Tuple[i]
	default:
		*dgs = append(*dgs, &Diagnostic{
			Summary: "Unsupported attribute",
			Detail:  fmt.Sprintf("This value does not have an attribute named %q.", key.AsString()),
			Subject: rng,
		})
		return NullVal()
	}
}

func evalBinary(e *BinaryExpr, ctx *EvalContext, dgs *Diagnostics) Value {
	l := evalExpr(e.L, ctx, dgs)
	switch e.Op {
	case "&&":
		if !l.Truthy() {
			return BoolVal(false)
		}
		return BoolVal(evalExpr(e.R, ctx, dgs).Truthy())
	case "||":
		if l.Truthy() {
			return BoolVal(true)
		}
		return BoolVal(evalExpr(e.R, ctx, dgs).Truthy())
	}
	r := evalExpr(e.R, ctx, dgs)
	switch e.Op {
	case "+":
		if l.Kind == KindString || r.Kind == KindString {
			return StringVal(l.AsString() + r.AsString())
		}
		return NumberVal(l.Num+r.Num, "")
	case "-":
		return NumberVal(l.Num-r.Num, "")
	case "*":
		return NumberVal(l.Num*r.Num, "")
	case "/":
		return NumberVal(l.Num/r.Num, "")
	case "%":
		return NumberVal(float64(int64(l.Num)%int64(r.Num)), "")
	case "==":
		return BoolVal(l.Equal(r))
	case "!=":
		return BoolVal(!l.Equal(r))
	case "<":
		return BoolVal(l.Num < r.Num)
	case "<=":
		return BoolVal(l.Num <= r.Num)
	case ">":
		return BoolVal(l.Num > r.Num)
	case ">=":
		return BoolVal(l.Num >= r.Num)
	}
	return NullVal()
}

