				return hcl.StringVal(strings.ToUpper(args[0].AsString())), nil
			},
			"lower": func(args []hcl.Value) (hcl.Value, error) {
				return hcl.StringVal(strings.ToLower(args[0].AsString())), nil
			},
			"trim": func(args []hcl.Value) (hcl.Value, error) {
				if len(args) < 2 {
					return hcl.StringVal(strings.TrimSpace(args[0].AsString())), nil
				}
				return hcl.StringVal(strings.Trim(args[0].AsString(), args[1].AsString())), nil
			},
