					parts = append(parts, e.AsString())
				}
				return hcl.StringVal(strings.Join(parts, args[0].AsString())), nil
			},
			"file": func(args []hcl.Value) (hcl.Value, error) {
				b, err := os.ReadFile(args[0].AsString())
				if err != nil {
					return hcl.NullVal(), err
				}
				return hcl.StringVal(string(b)), nil
			},
			"abspath": func(args []hcl.Value) (hcl.Value, error) {
				p, err := filepath.Abs(args[0].AsString())
				if err != nil {
					return hcl.NullVal(), err
				}
				return hcl.StringVal(p), nil
			},
			"print": func(args []hcl.Value) (hcl.Value, error) {
				fmt.Fprintln(os.Stdout, args[0].AsString())
				return args[0], nil
			},
			"urlescape": func(args []hcl.Value) (hcl.Value, error) {
				return hcl.StringVal(args[0].AsString()), nil
			},
		},
	}
}

