// Package sqlite implements the subset of SQLite that atlas needs: reading and
// writing database files, plus a small SQL engine over them.
package sqlite

import (
	"encoding/binary"
	"fmt"
	"math"
)

// putVarint appends a SQLite variable length integer to dst.
func putVarint(dst []byte, v uint64) []byte {
	if v>>56 != 0 {
		var b [9]byte
		for i := 7; i >= 0; i-- {
			b[i] = byte(v&0x7f) | 0x80
			v >>= 7
		}
		b[8] = byte(v & 0xff)
		// The 9 byte form stores the low 8 bits raw in the last byte.
		return append(dst, encode9(v)...)
	}
	var buf [9]byte
	n := 0
	for {
		buf[n] = byte(v & 0x7f)
		n++
		v >>= 7
		if v == 0 {
			break
		}
	}
	for i := n - 1; i >= 0; i-- {
		b := buf[i]
		if i != 0 {
			b |= 0x80
		}
		dst = append(dst, b)
	}
	return dst
}

func encode9(v uint64) []byte {
	out := make([]byte, 9)
	out[8] = byte(v)
	v >>= 8
	for i := 7; i >= 0; i-- {
		out[i] = byte(v&0x7f) | 0x80
		v >>= 7
	}
	out[0] &= 0xff
	return out
}

