			types = append(types, uint64(len(v.Str))*2+13)
			body = append(body, v.Str...)
		case KindBlob:
			types = append(types, uint64(len(v.Blob))*2+12)
			body = append(body, v.Blob...)
		}
	}
	var hdr []byte
	for _, t := range types {
		hdr = putVarint(hdr, t)
	}
	hdrLen := len(hdr) + 1
	if varintLen(uint64(hdrLen)) > 1 {
		hdrLen = len(hdr) + varintLen(uint64(len(hdr)+2))
	}
	out := putVarint(nil, uint64(hdrLen))
	out = append(out, hdr...)
	return append(out, body...)
}

// decodeRecord parses a SQLite record into its column values.
func decodeRecord(rec []byte) []Value {
	hdrLen, n := getVarint(rec)
	if int(hdrLen) > len(rec) {
		return nil
	}
	var (
		types []uint64
		out   []Value
	)
	for i := n; i < int(hdrLen); {
		t, w := getVarint(rec[i:])
		if w == 0 {
			break
		}
		types = append(types, t)
		i += w
	}
	body := rec[hdrLen:]
	off := 0
	read := func(n int) []byte {
		if off+n > len(body) {
			n = len(body) - off
		}
		if n < 0 {
			n = 0
		}
		b := body[off : off+n]
		off += n
		return b
	}
	for _, t := range types {
		switch {
		case t == 0:
			out = append(out, Null())
		case t >= 1 && t <= 6:
			size := []int{0, 1, 2, 3, 4, 6, 8}[t]
			out = append(out, Int64(decodeInt(read(size))))
		case t == 7:
			b := read(8)
			if len(b) == 8 {
				out = append(out, Float(math.Float64frombits(binary.BigEndian.Uint64(b))))
			} else {
				out = append(out, Float(0))
			}
		case t == 8:
			out = append(out, Int64(0))
		case t == 9:
			out = append(out, Int64(1))
		case t >= 12 && t%2 == 0:
			out = append(out, Blob(append([]byte(nil), read(int(t-12)/2)...)))
		case t >= 13 && t%2 == 1:
			out = append(out, Text(string(read(int(t-13)/2))))
		default:
			out = append(out, Null())
		}
	}
	return out
}

func decodeInt(b []byte) int64 {
	if len(b) == 0 {
		return 0
	}
	v := int64(0)
	if b[0]&0x80 != 0 {
		v = -1
	}
	for _, c := range b {
		v = v<<8 | int64(c)
	}
	return v
}

