// Package sqlite implements the subset of SQLite that atlas needs: reading and
// writing database files, plus a small SQL engine over them.
package sqlite

import (
	"encoding/binary"
	"fmt"
	"math"
)

// putVarint appends a SQLite variable length integer to dst.
func putVarint(dst []byte, v uint64) []byte {
	if v>>56 != 0 {
		var b [9]byte
		b[8] = byte(v)
		v >>= 8
		for i := 7; i >= 0; i-- {
			b[i] = byte(v&0x7f) | 0x80
			v >>= 7
		}
		return append(dst, b[:]...)
	}
	var buf [9]byte
	n := 0
	for {
		buf[n] = byte(v & 0x7f)
		n++
		v >>= 7
		if v == 0 {
			break
		}
	}
	for i := n - 1; i >= 0; i-- {
		b := buf[i]
		if i != 0 {
			b |= 0x80
		}
		dst = append(dst, b)
	}
	return dst
}

// varintLen reports how many bytes putVarint would write for v.
func varintLen(v uint64) int {
	if v>>56 != 0 {
		return 9
	}
	n := 1
	for v >>= 7; v != 0; v >>= 7 {
		n++
	}
	return n
}

// getVarint decodes a variable length integer, returning it and its width.
func getVarint(src []byte) (uint64, int) {
	var v uint64
	for i := 0; i < 8; i++ {
		if i >= len(src) {
			return v, i
		}
		c := src[i]
		v = v<<7 | uint64(c&0x7f)
		if c&0x80 == 0 {
			return v, i + 1
		}
	}
	if len(src) < 9 {
		return v, len(src)
	}
	return v<<8 | uint64(src[8]), 9
}

// ValueKind identifies the storage class of a cell value.
type ValueKind int

// The SQLite storage classes.
const (
	KindNull ValueKind = iota
	KindInt
	KindFloat
	KindText
	KindBlob
)

// Value is a single column value.
type Value struct {
	Kind ValueKind
	Int  int64
	Real float64
	Str  string
	Blob []byte
}

// Null is the NULL value.
func Null() Value { return Value{Kind: KindNull} }

// Int64 wraps an integer.
func Int64(i int64) Value { return Value{Kind: KindInt, Int: i} }

// Float wraps a real.
func Float(f float64) Value { return Value{Kind: KindFloat, Real: f} }

// Text wraps a string.
func Text(s string) Value { return Value{Kind: KindText, Str: s} }

// Blob wraps a byte slice.
func Blob(b []byte) Value { return Value{Kind: KindBlob, Blob: b} }

// String renders the value for display purposes.
func (v Value) String() string {
	switch v.Kind {
	case KindNull:
		return "NULL"
	case KindInt:
		return fmt.Sprintf("%d", v.Int)
	case KindFloat:
		return formatReal(v.Real)
	case KindText:
		return v.Str
	default:
		return string(v.Blob)
	}
}

func formatReal(f float64) string {
	if f == math.Trunc(f) && math.Abs(f) < 1e15 {
		return fmt.Sprintf("%.1f", f)
	}
	return fmt.Sprintf("%g", f)
}

// encodeRecord serialises a row into the SQLite record format.
func encodeRecord(vals []Value) []byte {
	var (
		types []uint64
		body  []byte
	)
	for _, v := range vals {
		switch v.Kind {
		case KindNull:
			types = append(types, 0)
		case KindInt:
			switch n := v.Int; {
			case n == 0:
				types = append(types, 8)
			case n == 1:
				types = append(types, 9)
			case n >= -128 && n <= 127:
				types = append(types, 1)
				body = append(body, byte(n))
			case n >= -32768 && n <= 32767:
				types = append(types, 2)
				body = append(body, byte(n>>8), byte(n))
			case n >= -8388608 && n <= 8388607:
				types = append(types, 3)
				body = append(body, byte(n>>16), byte(n>>8), byte(n))
			case n >= -2147483648 && n <= 2147483647:
				types = append(types, 4)
				body = append(body, byte(n>>24), byte(n>>16), byte(n>>8), byte(n))
			default:
				types = append(types, 6)
				var b [8]byte
				binary.BigEndian.PutUint64(b[:], uint64(n))
				body = append(body, b[:]...)
			}
		case KindFloat:
			types = append(types, 7)
			var b [8]byte
			binary.BigEndian.PutUint64(b[:], math.Float64bits(v.Real))
			body = append(body, b[:]...)
		case KindText:
			types = append(types, uint64(len(v.Str))*2+13)
			body = append(body, v.Str...)
		case KindBlob:
			types = append(types, uint64(len(v.Blob))*2+12)
			body = append(body, v.Blob...)
		}
	}
	var hdr []byte
	for _, t := range types {
		hdr = putVarint(hdr, t)
	}
	hdrLen := len(hdr) + 1
	if varintLen(uint64(hdrLen)) > 1 {
		hdrLen = len(hdr) + varintLen(uint64(len(hdr)+2))
	}
	out := putVarint(nil, uint64(hdrLen))
	out = append(out, hdr...)
	return append(out, body...)
}

// decodeRecord parses a SQLite record into its column values.
func decodeRecord(rec []byte) []Value {
	hdrLen, n := getVarint(rec)
	if int(hdrLen) > len(rec) {
		return nil
	}
	var (
		types []uint64
		out   []Value
	)
	for i := n; i < int(hdrLen); {
		t, w := getVarint(rec[i:])
		if w == 0 {
			break
		}
		types = append(types, t)
		i += w
	}
	body := rec[hdrLen:]
	off := 0
	read := func(n int) []byte {
		if off+n > len(body) {
			n = len(body) - off
		}
		if n < 0 {
			n = 0
		}
		b := body[off : off+n]
		off += n
		return b
	}
	for _, t := range types {
		switch {
		case t == 0:
			out = append(out, Null())
		case t >= 1 && t <= 6:
			size := []int{0, 1, 2, 3, 4, 6, 8}[t]
			out = append(out, Int64(decodeInt(read(size))))
		case t == 7:
			b := read(8)
			if len(b) == 8 {
				out = append(out, Float(math.Float64frombits(binary.BigEndian.Uint64(b))))
			} else {
				out = append(out, Float(0))
			}
		case t == 8:
			out = append(out, Int64(0))
		case t == 9:
			out = append(out, Int64(1))
		case t >= 12 && t%2 == 0:
			out = append(out, Blob(append([]byte(nil), read(int(t-12)/2)...)))
		case t >= 13 && t%2 == 1:
			out = append(out, Text(string(read(int(t-13)/2))))
		default:
			out = append(out, Null())
		}
	}
	return out
}

func decodeInt(b []byte) int64 {
	if len(b) == 0 {
		return 0
	}
	v := int64(0)
	if b[0]&0x80 != 0 {
		v = -1
	}
	for _, c := range b {
		v = v<<8 | int64(c)
	}
	return v
}

