package sqlite

import (
	"encoding/binary"
	"fmt"
)

const (
	headerMagic     = "SQLite format 3\x00"
	defaultPageSize = 4096
)

// btreeEntry is one record in a b-tree: a rowid for table trees, or a key
// payload for index trees.
type btreeEntry struct {
	Key     int64  // rowid, table trees only
	Payload []byte // record bytes
}

// image is a database file being read or written page by page.
type image struct {
	pageSize int
	pages    [][]byte // pages[0] is page 1
}

func newImage(pageSize int) *image {
	return &image{pageSize: pageSize}
}

// alloc reserves a new zeroed page and returns its 1-based number.
func (im *image) alloc() int {
	im.pages = append(im.pages, make([]byte, im.pageSize))
	return len(im.pages)
}

// page returns the 1-based page contents.
func (im *image) page(n int) []byte {
	if n < 1 || n > len(im.pages) {
		return nil
	}
	return im.pages[n-1]
}

// readImage splits raw file bytes into pages.
func readImage(data []byte) (*image, error) {
	if len(data) == 0 {
		return newImage(defaultPageSize), nil
	}
	if len(data) < 100 || string(data[:16]) != headerMagic {
		return nil, fmt.Errorf("file is not a database")
	}
	ps := int(binary.BigEndian.Uint16(data[16:18]))
	if ps == 1 {
		ps = 65536
	}
	if ps < 512 || ps&(ps-1) != 0 {
		return nil, fmt.Errorf("file is not a database")
	}
	im := newImage(ps)
	for off := 0; off < len(data); off += ps {
		end := off + ps
		if end > len(data) {
			end = len(data)
		}
		p := make([]byte, ps)
		copy(p, data[off:end])
		im.pages = append(im.pages, p)
	}
	return im, nil
}

// bytes flattens the image back into file contents.
func (im *image) bytes() []byte {
	out := make([]byte, 0, len(im.pages)*im.pageSize)
	for _, p := range im.pages {
		out = append(out, p...)
	}
	return out
}

// pageOffset is the number of header bytes reserved at the start of a page.
func pageOffset(n int) int {
	if n == 1 {
		return 100
	}
	return 0
}

// readBTree walks the b-tree rooted at root and returns its entries in order.
func (im *image) readBTree(root int, table bool) ([]btreeEntry, error) {
	var out []btreeEntry
	seen := map[int]bool{}
	var walk func(n int) error
	walk = func(n int) error {
		if n < 1 || n > len(im.pages) || seen[n] {
			return nil
		}
		seen[n] = true
		p := im.page(n)
		off := pageOffset(n)
		typ := p[off]
		cells := int(binary.BigEndian.Uint16(p[off+3 : off+5]))
		hdrSize := 8
		if typ == 2 || typ == 5 {
			hdrSize = 12
		}
		ptrs := off + hdrSize
		for i := 0; i < cells; i++ {
			if ptrs+2*i+2 > len(p) {
				break
			}
			cp := int(binary.BigEndian.Uint16(p[ptrs+2*i : ptrs+2*i+2]))
			if cp <= 0 || cp >= len(p) {
				continue
			}
			switch typ {
			case 13: // table leaf
				sz, n1 := getVarint(p[cp:])
				key, n2 := getVarint(p[cp+n1:])
				payload, err := im.readPayload(p, cp+n1+n2, int(sz), true)
				if err != nil {
					return err
				}
				out = append(out, btreeEntry{Key: int64(key), Payload: payload})
			case 5: // table interior
				child := int(binary.BigEndian.Uint32(p[cp : cp+4]))
				if err := walk(child); err != nil {
					return err
				}
			case 10: // index leaf
				sz, n1 := getVarint(p[cp:])
				payload, err := im.readPayload(p, cp+n1, int(sz), false)
				if err != nil {
					return err
				}
				out = append(out, btreeEntry{Payload: payload})
			case 2: // index interior
				child := int(binary.BigEndian.Uint32(p[cp : cp+4]))
				if err := walk(child); err != nil {
					return err
				}
				sz, n1 := getVarint(p[cp+4:])
				payload, err := im.readPayload(p, cp+4+n1, int(sz), false)
				if err != nil {
					return err
				}
				out = append(out, btreeEntry{Payload: payload})
			}
		}
		if typ == 2 || typ == 5 {
			right := int(binary.BigEndian.Uint32(p[off+8 : off+12]))
			if err := walk(right); err != nil {
				return err
			}
		}
		return nil
	}
	if err := walk(root); err != nil {
		return nil, err
	}
	return out, nil
}

// readPayload reads size bytes starting at start, following overflow pages.
func (im *image) readPayload(p []byte, start, size int, table bool) ([]byte, error) {
	usable := im.pageSize
	local := size
	var maxLocal int
	if table {
		maxLocal = usable - 35
	} else {
		maxLocal = (usable-12)*64/255 - 23
	}
	if size > maxLocal {
		minLocal := (usable-12)*32/255 - 23
		k := minLocal + (size-minLocal)%(usable-4)
		if k <= maxLocal {
			local = k
		} else {
			local = minLocal
		}
	}
	if start+local > len(p) {
		local = len(p) - start
	}
	if local < 0 {
		return nil, fmt.Errorf("database disk image is malformed")
	}
	out := make([]byte, 0, size)
	out = append(out, p[start:start+local]...)
	if local == size {
		return out, nil
	}
	next := int(binary.BigEndian.Uint32(p[start+local : start+local+4]))
	for next != 0 && len(out) < size {
		op := im.page(next)
		if op == nil {
			return nil, fmt.Errorf("database disk image is malformed")
		}
		n := size - len(out)
		if n > usable-4 {
			n = usable - 4
		}
		out = append(out, op[4:4+n]...)
		next = int(binary.BigEndian.Uint32(op[:4]))
	}
	return out, nil
}

// cell is a serialised b-tree cell waiting to be placed on a page.
type cell struct {
	body []byte
	key  int64
}

// writeBTree bulk loads entries into a freshly built b-tree and returns the
// root page. When rootPage is non-zero the tree is rooted at that page.
func (im *image) writeBTree(entries []btreeEntry, table bool, rootPage int) int {
	cells := make([]cell, 0, len(entries))
	for _, e := range entries {
		cells = append(cells, cell{body: im.makeLeafCell(e, table), key: e.Key})
	}
	leafType := byte(13)
	if !table {
		leafType = 10
	}
	pages := im.packPages(cells, leafType, rootPage)
	for len(pages) > 1 {
		pages = im.packInterior(pages, table, rootPage)
	}
	if len(pages) == 0 {
		// Empty tree: a single leaf page.
		n := rootPage
		if n == 0 {
			n = im.alloc()
		}
		im.initPage(n, leafType)
		return n
	}
	return pages[0].num
}

// pageRef is a written page together with the highest key it contains.
type pageRef struct {
	num int
	key int64
}

// makeLeafCell serialises one entry, spilling to overflow pages if needed.
func (im *image) makeLeafCell(e btreeEntry, table bool) []byte {
	usable := im.pageSize
	size := len(e.Payload)
	var maxLocal int
	if table {
		maxLocal = usable - 35
	} else {
		maxLocal = (usable-12)*64/255 - 23
	}
	local := size
	if size > maxLocal {
		minLocal := (usable-12)*32/255 - 23
		k := minLocal + (size-minLocal)%(usable-4)
		if k <= maxLocal {
			local = k
		} else {
			local = minLocal
		}
	}
	var head []byte
	head = putVarint(head, uint64(size))
	if table {
		head = putVarint(head, uint64(e.Key))
	}
	body := append(head, e.Payload[:local]...)
	if local == size {
		return body
	}
	rest := e.Payload[local:]
	first := im.writeOverflow(rest)
	var np [4]byte
	binary.BigEndian.PutUint32(np[:], uint32(first))
	return append(body, np[:]...)
}

func (im *image) writeOverflow(rest []byte) int {
	usable := im.pageSize
	var nums []int
	for i := 0; i < len(rest); i += usable - 4 {
		nums = append(nums, im.alloc())
	}
	for i, n := range nums {
		p := im.page(n)
		start := i * (usable - 4)
		end := start + usable - 4
		if end > len(rest) {
			end = len(rest)
		}
		copy(p[4:], rest[start:end])
		if i+1 < len(nums) {
			binary.BigEndian.PutUint32(p[:4], uint32(nums[i+1]))
		}
	}
	return nums[0]
}

func (im *image) initPage(n int, typ byte) {
	p := im.page(n)
	off := pageOffset(n)
	for i := range p[off:] {
		p[off+i] = 0
	}
	p[off] = typ
	binary.BigEndian.PutUint16(p[off+5:off+7], uint16(im.pageSize%65536))
}

// packPages lays cells out over as many leaf pages as required.
func (im *image) packPages(cells []cell, typ byte, rootPage int) []pageRef {
	var (
		out     []pageRef
		cur     []cell
		curSize int
	)
	flush := func() {
		if len(cur) == 0 {
			return
		}
		n := 0
		if rootPage != 0 && len(out) == 0 && curSize+len(cur)*2+8 <= im.pageSize-100 {
			n = rootPage
		}
		if n == 0 {
			n = im.alloc()
		}
		im.writeLeaf(n, cur, typ)
		out = append(out, pageRef{num: n, key: cur[len(cur)-1].key})
		cur, curSize = nil, 0
	}
	for _, c := range cells {
		avail := im.pageSize - 8 - 2*(len(cur)+1)
		if rootPage != 0 && len(out) == 0 {
			avail -= 100
		}
		if len(cur) > 0 && curSize+len(c.body) > avail {
			flush()
		}
		cur = append(cur, c)
		curSize += len(c.body)
	}
	flush()
	return out
}

func (im *image) writeLeaf(n int, cells []cell, typ byte) {
	p := im.page(n)
	off := pageOffset(n)
	for i := off; i < len(p); i++ {
		p[i] = 0
	}
	p[off] = typ
	binary.BigEndian.PutUint16(p[off+3:off+5], uint16(len(cells)))
	content := im.pageSize
	ptr := off + 8
	for i, c := range cells {
		content -= len(c.body)
		copy(p[content:], c.body)
		binary.BigEndian.PutUint16(p[ptr+2*i:ptr+2*i+2], uint16(content))
	}
	binary.BigEndian.PutUint16(p[off+5:off+7], uint16(content%65536))
}

// packInterior builds the next level up from the given child pages.
func (im *image) packInterior(children []pageRef, table bool, rootPage int) []pageRef {
	var (
		out     []pageRef
		cur     []pageRef
		curSize int
	)
	cellSize := func() int {
		if table {
			return 4 + 9
		}
		return 4 + 2
	}
	flush := func(last pageRef) {
		n := 0
