package sqlite

import (
	"encoding/binary"
	"fmt"
)

const (
	headerMagic     = "SQLite format 3\x00"
	defaultPageSize = 4096
)

// btreeEntry is one record in a b-tree: a rowid for table trees, or a key
// payload for index trees.
type btreeEntry struct {
	Key     int64  // rowid, table trees only
	Payload []byte // record bytes
}

// image is a database file being read or written page by page.
type image struct {
	pageSize int
	pages    [][]byte // pages[0] is page 1
}

func newImage(pageSize int) *image {
	return &image{pageSize: pageSize}
}

// alloc reserves a new zeroed page and returns its 1-based number.
func (im *image) alloc() int {
	im.pages = append(im.pages, make([]byte, im.pageSize))
	return len(im.pages)
}

// page returns the 1-based page contents.
func (im *image) page(n int) []byte {
	if n < 1 || n > len(im.pages) {
		return nil
	}
	return im.pages[n-1]
}

// readImage splits raw file bytes into pages.
func readImage(data []byte) (*image, error) {
	if len(data) == 0 {
		return newImage(defaultPageSize), nil
	}
	if len(data) < 100 || string(data[:16]) != headerMagic {
		return nil, fmt.Errorf("file is not a database")
	}
	ps := int(binary.BigEndian.Uint16(data[16:18]))
	if ps == 1 {
		ps = 65536
	}
	if ps < 512 || ps&(ps-1) != 0 {
		return nil, fmt.Errorf("file is not a database")
	}
	im := newImage(ps)
	for off := 0; off < len(data); off += ps {
		end := off + ps
		if end > len(data) {
			end = len(data)
		}
		p := make([]byte, ps)
		copy(p, data[off:end])
		im.pages = append(im.pages, p)
	}
	return im, nil
}

// bytes flattens the image back into file contents.
func (im *image) bytes() []byte {
	out := make([]byte, 0, len(im.pages)*im.pageSize)
	for _, p := range im.pages {
		out = append(out, p...)
	}
	return out
}

// pageOffset is the number of header bytes reserved at the start of a page.
func pageOffset(n int) int {
	if n == 1 {
		return 100
	}
	return 0
}

// readBTree walks the b-tree rooted at root and returns its entries in order.
func (im *image) readBTree(root int, table bool) ([]btreeEntry, error) {
	var out []btreeEntry
	seen := map[int]bool{}
	var walk func(n int) error
	walk = func(n int) error {
		if n < 1 || n > len(im.pages) || seen[n] {
			return nil
		}
		seen[n] = true
		p := im.page(n)
		off := pageOffset(n)
		typ := p[off]
		cells := int(binary.BigEndian.Uint16(p[off+3 : off+5]))
		hdrSize := 8
		if typ == 2 || typ == 5 {
			hdrSize = 12
		}
		ptrs := off + hdrSize
		for i := 0; i < cells; i++ {
			if ptrs+2*i+2 > len(p) {
				break
			}
			cp := int(binary.BigEndian.Uint16(p[ptrs+2*i : ptrs+2*i+2]))
			if cp <= 0 || cp >= len(p) {
				continue
			}
