			case 13: // table leaf
				sz, n1 := getVarint(p[cp:])
				key, n2 := getVarint(p[cp+n1:])
				payload, err := im.readPayload(p, cp+n1+n2, int(sz), true)
				if err != nil {
					return err
				}
				out = append(out, btreeEntry{Key: int64(key), Payload: payload})
			case 5: // table interior
				child := int(binary.BigEndian.Uint32(p[cp : cp+4]))
				if err := walk(child); err != nil {
					return err
				}
			case 10: // index leaf
				sz, n1 := getVarint(p[cp:])
				payload, err := im.readPayload(p, cp+n1, int(sz), false)
				if err != nil {
					return err
				}
				out = append(out, btreeEntry{Payload: payload})
			case 2: // index interior
				child := int(binary.BigEndian.Uint32(p[cp : cp+4]))
				if err := walk(child); err != nil {
					return err
				}
				sz, n1 := getVarint(p[cp+4:])
				payload, err := im.readPayload(p, cp+4+n1, int(sz), false)
				if err != nil {
					return err
				}
				out = append(out, btreeEntry{Payload: payload})
			}
