import "encoding/binary"

// pageRef is a written page together with the largest key it contains, which
// becomes the divider in the parent interior page.
type pageRef struct {
	num     int
	key     int64
	divider []byte
}

// writeBTree bulk loads entries into a freshly built b-tree and returns the
// root page number. When rootPage is non-zero the finished root is relocated
// there, and every page of the tree reserves room for the file header.
func (im *image) writeBTree(entries []btreeEntry, table bool, rootPage int) int {
	reserve := 0
	if rootPage != 0 {
		reserve = 100
	}
	leafType := byte(13)
	if !table {
		leafType = 10
	}
	cells := make([]cell, 0, len(entries))
	for _, e := range entries {
		cells = append(cells, cell{body: im.makeLeafCell(e, table), key: e.Key, divider: e.Payload})
	}
	level := im.packLeaves(cells, leafType, reserve)
	if len(level) == 0 {
		n := rootPage
		if n == 0 {
			n = im.alloc()
		}
		im.initPage(n, leafType)
		return n
	}
	for len(level) > 1 {
		level = im.packInterior(level, table, reserve)
	}
	if rootPage == 0 {
		return level[0].num
	}
	im.relocate(level[0].num, rootPage)
	return rootPage
}

// relocate copies a page built without the file header into page 1.
func (im *image) relocate(from, to int) {
	src, dst := im.page(from), im.page(to)
	typ := src[0]
	hdr := 8
	if typ == 2 || typ == 5 {
		hdr = 12
	}
	n := int(binary.BigEndian.Uint16(src[3:5]))
	for i := 100; i < len(dst); i++ {
		dst[i] = 0
	}
	copy(dst[100:], src[:hdr+2*n])
	content := int(binary.BigEndian.Uint16(src[5:7]))
	if content == 0 {
		content = 65536
	}
	copy(dst[content:], src[content:])
	if from == len(im.pages) {
		im.pages = im.pages[:len(im.pages)-1]
	}
}

// cell is a serialised leaf cell waiting to be placed on a page.
type cell struct {
	body    []byte
	key     int64
	divider []byte
}

func (im *image) initPage(n int, typ byte) {
	p := im.page(n)
	off := pageOffset(n)
	for i := off; i < len(p); i++ {
		p[i] = 0
	}
	p[off] = typ
	binary.BigEndian.PutUint16(p[off+5:off+7], uint16(im.pageSize%65536))
}

// packLeaves lays the cells out over as many leaf pages as required.
func (im *image) packLeaves(cells []cell, typ byte, reserve int) []pageRef {
	var (
		out     []pageRef
		cur     []cell
		curSize int
	)
	flush := func() {
		if len(cur) == 0 {
			return
		}
		n := im.alloc()
		im.writeLeaf(n, cur, typ)
		out = append(out, pageRef{num: n, key: cur[len(cur)-1].key, divider: cur[len(cur)-1].divider})
		cur, curSize = nil, 0
	}
	for _, c := range cells {
		avail := im.pageSize - reserve - 8 - 2*(len(cur)+1)
		if len(cur) > 0 && curSize+len(c.body) > avail {
			flush()
		}
		cur = append(cur, c)
		curSize += len(c.body)
	}
	flush()
	return out
