	p := im.page(n)
	for i := range p {
		p[i] = 0
	}
	p[0] = typ
	binary.BigEndian.PutUint16(p[3:5], uint16(len(cells)))
	content := im.pageSize
	for i, c := range cells {
		content -= len(c.body)
		copy(p[content:], c.body)
		binary.BigEndian.PutUint16(p[8+2*i:10+2*i], uint16(content))
	}
	binary.BigEndian.PutUint16(p[5:7], uint16(content%65536))
}

