	var (
		out     []pageRef
		cur     []pageRef
		curSize int
	)
	flush := func(last pageRef) {
		n := im.alloc()
		im.writeInterior(n, cur, last, table)
		out = append(out, pageRef{num: n, key: last.key, divider: last.divider})
		cur, curSize = nil, 0
