		size := len(im.interiorCell(ch, table))
		avail := im.pageSize - reserve - 12 - 2*(len(cur)+1)
		if len(cur) > 0 && curSize+size > avail {
			flush(ch)
			continue
		}
		cur = append(cur, ch)
		curSize += size
	}
	return out
}

func (im *image) interiorCell(c pageRef, table bool) []byte {
	var np [4]byte
	binary.BigEndian.PutUint32(np[:], uint32(c.num))
	body := append([]byte(nil), np[:]...)
	if table {
		return putVarint(body, uint64(c.key))
	}
	body = putVarint(body, uint64(len(c.divider)))
	return append(body, c.divider...)
}

func (im *image) writeInterior(n int, cells []pageRef, right pageRef, table bool) {
	p := im.page(n)
	for i := range p {
		p[i] = 0
	}
	if table {
		p[0] = 5
	} else {
		p[0] = 2
	}
	binary.BigEndian.PutUint16(p[3:5], uint16(len(cells)))
	binary.BigEndian.PutUint32(p[8:12], uint32(right.num))
	content := im.pageSize
	for i, c := range cells {
		body := im.interiorCell(c, table)
		content -= len(body)
		copy(p[content:], body)
		binary.BigEndian.PutUint16(p[12+2*i:14+2*i], uint16(content))
	}
	binary.BigEndian.PutUint16(p[5:7], uint16(content%65536))
}

