}
func isIdentByte(c byte) bool {
	return c == '_' || c == '$' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80
}

// SplitStatements breaks a SQL script into individual statements.
func SplitStatements(s string) []string {
