				case "TRIGGER":
					inTrigger = true
				case "BEGIN":
					if inTrigger {
						beginDepth++
					}
				case "END":
					if inTrigger {
						beginDepth--
						if beginDepth <= 0 {
							inTrigger = false
						}
					}
				}
				i = j
				continue
			}
			i++
		}
	}
	if rest := strings.TrimSpace(s[start:]); rest != "" {
		out = append(out, rest)
	}
	return out
}

// parser walks a token slice.
type sqlParser struct {
	toks []tok
	i    int
}

func newSQLParser(s string) (*sqlParser, error) {
	toks, err := lexSQL(s)
	if err != nil {
		return nil, err
	}
	return &sqlParser{toks: toks}, nil
}

func (p *sqlParser) peek() tok  { return p.toks[p.i] }
func (p *sqlParser) next() tok  { t := p.toks[p.i]; if p.i < len(p.toks)-1 { p.i++ }; return t }
func (p *sqlParser) eof() bool  { return p.peek().kind == tkEOF }

func (p *sqlParser) acceptKw(words ...string) bool {
	save := p.i
	for _, w := range words {
		t := p.peek()
		if t.kind != tkKeyword || t.text != w {
			p.i = save
			return false
		}
		p.next()
	}
	return true
}

func (p *sqlParser) acceptPunct(s string) bool {
	if t := p.peek(); t.kind == tkPunct && t.text == s {
		p.next()
		return true
	}
	return false
}

func (p *sqlParser) expectPunct(s string) error {
	if !p.acceptPunct(s) {
		return fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
	}
	return nil
}

// name reads an identifier or non-reserved keyword used as a name.
func (p *sqlParser) name() (string, error) {
	t := p.peek()
	if t.kind == tkIdent || t.kind == tkKeyword {
		p.next()
		return t.text, nil
	}
	return "", fmt.Errorf(`near "%s": syntax error`, t.raw)
}

// qualifiedName reads [schema.]name and returns the last part.
func (p *sqlParser) qualifiedName() (string, error) {
	n, err := p.name()
	if err != nil {
		return "", err
	}
	if p.acceptPunct(".") {
		return p.name()
	}
	return n, nil
}

func unquoteNum(s string) (Value, error) {
	if strings.HasPrefix(s, "0x") || strings.HasPrefix(s, "0X") {
		v, err := strconv.ParseInt(s[2:], 16, 64)
		if err != nil {
			return Null(), err
		}
		return Int64(v), nil
	}
	if !strings.ContainsAny(s, ".eE") {
		if v, err := strconv.ParseInt(s, 10, 64); err == nil {
			return Int64(v), nil
		}
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return Null(), err
	}
	return Float(f), nil
}

