package sqlite

import (
	"fmt"
	"strings"
)

// Expr is a SQL scalar expression.
type Expr interface {
	// SQL renders the expression back to text.
	SQL() string
}

// Lit is a literal constant.
type Lit struct {
	Val  Value
	Text string
}

// SQL renders the literal as written.
func (e *Lit) SQL() string { return e.Text }

// ColRef is a (possibly qualified) column reference.
type ColRef struct {
	Table string
	Name  string
	// Quoted keeps the original spelling of the identifier.
	Quoted string
}

// SQL renders the reference.
func (e *ColRef) SQL() string {
	if e.Table != "" {
		return e.Table + "." + e.Quoted
	}
	return e.Quoted
}

// Unary is a prefix operator application.
type Unary struct {
	Op string
	X  Expr
}

// SQL renders the operation.
func (e *Unary) SQL() string {
	if e.Op == "NOT" {
		return "NOT " + e.X.SQL()
	}
	return e.Op + e.X.SQL()
}

// Binary is an infix operator application.
type Binary struct {
	Op   string
	L, R Expr
}

// SQL renders the operation.
func (e *Binary) SQL() string {
	switch e.Op {
	case "AND", "OR", "IS", "IS NOT", "LIKE", "GLOB", "IN", "NOT IN":
		return e.L.SQL() + " " + e.Op + " " + e.R.SQL()
	default:
		return e.L.SQL() + " " + e.Op + " " + e.R.SQL()
	}
}

// Call is a function invocation.
type Call struct {
	Name     string
	Args     []Expr
	Star     bool
	Distinct bool
}

// SQL renders the call.
func (e *Call) SQL() string {
	if e.Star {
		return e.Name + "(*)"
	}
	parts := make([]string, len(e.Args))
	for i, a := range e.Args {
		parts[i] = a.SQL()
	}
	return e.Name + "(" + strings.Join(parts, ", ") + ")"
}

// Paren is a parenthesised expression.
type Paren struct{ X Expr }

// SQL renders the expression with its parentheses.
func (e *Paren) SQL() string { return "(" + e.X.SQL() + ")" }

// List is a parenthesised expression list, used by IN.
type List struct{ Items []Expr }

// SQL renders the list.
func (e *List) SQL() string {
	parts := make([]string, len(e.Items))
	for i, it := range e.Items {
		parts[i] = it.SQL()
	}
	return "(" + strings.Join(parts, ", ") + ")"
}

// Param is a bound parameter placeholder.
type Param struct{ Name string }

// SQL renders the placeholder.
func (e *Param) SQL() string { return e.Name }

// Cast is a CAST(x AS type) expression.
type Cast struct {
	X    Expr
	Type string
}

// SQL renders the cast.
func (e *Cast) SQL() string { return "CAST(" + e.X.SQL() + " AS " + e.Type + ")" }

// Between is `x BETWEEN lo AND hi`.
type Between struct {
	X, Lo, Hi Expr
	Not       bool
}

// SQL renders the comparison.
func (e *Between) SQL() string {
	op := " BETWEEN "
	if e.Not {
		op = " NOT BETWEEN "
	}
	return e.X.SQL() + op + e.Lo.SQL() + " AND " + e.Hi.SQL()
}

// CaseExpr is a CASE ... END expression.
type CaseExpr struct {
	Operand Expr
	Whens   []struct{ When, Then Expr }
	Else    Expr
}

// SQL renders the CASE expression.
func (e *CaseExpr) SQL() string {
	var b strings.Builder
	b.WriteString("CASE")
	if e.Operand != nil {
		b.WriteString(" " + e.Operand.SQL())
	}
	for _, w := range e.Whens {
		b.WriteString(" WHEN " + w.When.SQL() + " THEN " + w.Then.SQL())
	}
	if e.Else != nil {
		b.WriteString(" ELSE " + e.Else.SQL())
	}
	b.WriteString(" END")
	return b.String()
}

// Collate applies a collation to an expression.
type Collate struct {
	X    Expr
	Name string
}

// SQL renders the collation.
func (e *Collate) SQL() string { return e.X.SQL() + " COLLATE " + e.Name }

var binaryPrec = []map[string]bool{
	{"OR": true},
	{"AND": true},
	{"=": true, "==": true, "!=": true, "<>": true, "IS": true, "IN": true, "LIKE": true, "GLOB": true, "MATCH": true, "REGEXP": true},
	{"<": true, "<=": true, ">": true, ">=": true},
	{"&": true, "|": true, "<<": true, ">>": true},
	{"+": true, "-": true},
	{"*": true, "/": true, "%": true},
	{"||": true},
}

// parseExpr parses a full expression.
func (p *sqlParser) parseExpr() (Expr, error) { return p.parseBinaryExpr(0) }

func (p *sqlParser) parseBinaryExpr(level int) (Expr, error) {
	if level >= len(binaryPrec) {
		return p.parseUnaryExpr()
	}
	left, err := p.parseBinaryExpr(level + 1)
	if err != nil {
		return nil, err
	}
	for {
		op, ok := p.matchBinaryOp(level)
		if !ok {
			return left, nil
		}
		switch op {
		case "IN", "NOT IN":
			right, err := p.parseUnaryExpr()
			if err != nil {
				return nil, err
			}
			left = &Binary{Op: op, L: left, R: right}
			continue
		case "BETWEEN", "NOT BETWEEN":
			lo, err := p.parseBinaryExpr(level + 1)
			if err != nil {
				return nil, err
			}
			if !p.acceptKw("AND") {
				return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
			}
			hi, err := p.parseBinaryExpr(level + 1)
			if err != nil {
				return nil, err
			}
			left = &Between{X: left, Lo: lo, Hi: hi, Not: strings.HasPrefix(op, "NOT")}
			continue
		}
		right, err := p.parseBinaryExpr(level + 1)
		if err != nil {
			return nil, err
		}
		left = &Binary{Op: op, L: left, R: right}
	}
}

func (p *sqlParser) matchBinaryOp(level int) (string, bool) {
	ops := binaryPrec[level]
	t := p.peek()
	switch t.kind {
	case tkPunct:
		if ops[t.text] {
			p.next()
			return t.text, true
		}
	case tkKeyword:
		switch t.text {
		case "AND", "OR", "LIKE", "GLOB", "MATCH", "REGEXP", "IN":
			if ops[t.text] {
				p.next()
				return t.text, true
			}
		case "IS":
			if ops["IS"] {
				p.next()
				if p.acceptKw("NOT") {
					return "IS NOT", true
				}
				return "IS", true
			}
		case "BETWEEN":
			if ops["<"] {
				p.next()
				return "BETWEEN", true
			}
		case "NOT":
			if ops["IN"] || ops["<"] {
				save := p.i
				p.next()
				switch {
				case p.acceptKw("IN"):
					return "NOT IN", true
				case p.acceptKw("LIKE"):
					return "NOT LIKE", true
				case p.acceptKw("BETWEEN"):
					return "NOT BETWEEN", true
				}
				p.i = save
			}
		}
	}
	return "", false
}

func (p *sqlParser) parseUnaryExpr() (Expr, error) {
	t := p.peek()
	switch {
	case t.kind == tkKeyword && t.text == "NOT":
		p.next()
		x, err := p.parseUnaryExpr()
		if err != nil {
			return nil, err
		}
		return &Unary{Op: "NOT", X: x}, nil
	case t.kind == tkPunct && (t.text == "-" || t.text == "+" || t.text == "~"):
		p.next()
		x, err := p.parseUnaryExpr()
		if err != nil {
			return nil, err
		}
		return &Unary{Op: t.text, X: x}, nil
	}
	return p.parsePostfixExpr()
}

func (p *sqlParser) parsePostfixExpr() (Expr, error) {
	x, err := p.parsePrimaryExpr()
	if err != nil {
		return nil, err
	}
	for {
		switch t := p.peek(); {
		case t.kind == tkKeyword && t.text == "COLLATE":
			p.next()
			n, err := p.name()
			if err != nil {
				return nil, err
			}
			x = &Collate{X: x, Name: n}
		case t.kind == tkKeyword && (t.text == "ISNULL" || t.text == "NOTNULL"):
			p.next()
			op := "IS"
			if t.text == "NOTNULL" {
				op = "IS NOT"
			}
			x = &Binary{Op: op, L: x, R: &Lit{Val: Null(), Text: "NULL"}}
		default:
			return x, nil
		}
	}
}

func (p *sqlParser) parsePrimaryExpr() (Expr, error) {
	t := p.peek()
	switch {
	case t.kind == tkNumber:
		p.next()
		v, err := unquoteNum(t.text)
		if err != nil {
			return nil, err
		}
		return &Lit{Val: v, Text: t.raw}, nil
	case t.kind == tkString:
		p.next()
		return &Lit{Val: Text(t.text), Text: t.raw}, nil
	case t.kind == tkBlob:
		p.next()
		return &Lit{Val: Blob(hexBytes(t.text)), Text: t.raw}, nil
	case t.kind == tkParam:
		p.next()
		return &Param{Name: t.text}, nil
	case t.kind == tkPunct && t.text == "(":
		p.next()
		first, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if p.acceptPunct(",") {
			items := []Expr{first}
			for {
				e, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				items = append(items, e)
				if !p.acceptPunct(",") {
					break
				}
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, err
			}
			return &List{Items: items}, nil
		}
		if err := p.expectPunct(")"); err != nil {
			return nil, err
		}
		return &Paren{X: first}, nil
	case t.kind == tkKeyword:
		switch t.text {
		case "NULL":
			p.next()
			return &Lit{Val: Null(), Text: "NULL"}, nil
		case "CURRENT_TIMESTAMP", "CURRENT_DATE", "CURRENT_TIME":
			p.next()
			return &ColRef{Name: t.text, Quoted: t.text}, nil
		case "CAST":
			p.next()
			if err := p.expectPunct("("); err != nil {
				return nil, err
			}
			x, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if !p.acceptKw("AS") {
				return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
			}
			ty, _, err := p.parseTypeName()
			if err != nil {
				return nil, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, err
			}
			return &Cast{X: x, Type: ty}, nil
		case "CASE":
			return p.parseCase()
		case "EXISTS", "SELECT":
			return nil, fmt.Errorf("subqueries are not supported")
		}
	}
	if t.kind == tkIdent || t.kind == tkKeyword {
		p.next()
		name := t.text
		quoted := t.raw
		if p.acceptPunct(".") {
			n2, err := p.name()
			if err != nil {
				return nil, err
			}
			return &ColRef{Table: name, Name: n2, Quoted: n2}, nil
		}
		if p.peek().kind == tkPunct && p.peek().text == "(" {
			p.next()
			call := &Call{Name: name}
			if p.acceptPunct("*") {
				call.Star = true
				if err := p.expectPunct(")"); err != nil {
					return nil, err
				}
				return call, nil
			}
			if p.acceptKw("DISTINCT") {
				call.Distinct = true
			}
			if !p.acceptPunct(")") {
				for {
					a, err := p.parseExpr()
					if err != nil {
						return nil, err
					}
					call.Args = append(call.Args, a)
					if !p.acceptPunct(",") {
						break
					}
				}
				if err := p.expectPunct(")"); err != nil {
					return nil, err
				}
			}
			return call, nil
		}
		return &ColRef{Name: name, Quoted: quoted}, nil
	}
	return nil, fmt.Errorf(`near "%s": syntax error`, t.raw)
}

func (p *sqlParser) parseCase() (Expr, error) {
	p.next() // CASE
	e := &CaseExpr{}
	if !(p.peek().kind == tkKeyword && p.peek().text == "WHEN") {
		x, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		e.Operand = x
	}
	for p.acceptKw("WHEN") {
		w, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if !p.acceptKw("THEN") {
			return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
		}
		t, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		e.Whens = append(e.Whens, struct{ When, Then Expr }{w, t})
	}
	if p.acceptKw("ELSE") {
		x, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		e.Else = x
	}
	if !p.acceptKw("END") {
		return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
	}
	return e, nil
}

func hexBytes(s string) []byte {
	out := make([]byte, 0, len(s)/2)
	for i := 0; i+1 < len(s); i += 2 {
		out = append(out, hexVal(s[i])<<4|hexVal(s[i+1]))
	}
	return out
}

func hexVal(c byte) byte {
	switch {
	case c >= '0' && c <= '9':
		return c - '0'
	case c >= 'a' && c <= 'f':
		return c - 'a' + 10
	case c >= 'A' && c <= 'F':
		return c - 'A' + 10
	}
	return 0
}

