// Call is a function invocation.
type Call struct {
	Name     string
	Args     []Expr
	Star     bool
	Distinct bool
}

// SQL renders the call.
func (e *Call) SQL() string {
	if e.Star {
		return e.Name + "(*)"
	}
	parts := make([]string, len(e.Args))
	for i, a := range e.Args {
		parts[i] = a.SQL()
	}
	return e.Name + "(" + strings.Join(parts, ", ") + ")"
}

// Paren is a parenthesised expression.
type Paren struct{ X Expr }

// SQL renders the expression with its parentheses.
func (e *Paren) SQL() string { return "(" + e.X.SQL() + ")" }

// List is a parenthesised expression list, used by IN.
type List struct{ Items []Expr }

// SQL renders the list.
func (e *List) SQL() string {
	parts := make([]string, len(e.Items))
	for i, it := range e.Items {
		parts[i] = it.SQL()
	}
	return "(" + strings.Join(parts, ", ") + ")"
}

// Param is a bound parameter placeholder.
type Param struct{ Name string }

// SQL renders the placeholder.
func (e *Param) SQL() string { return e.Name }

// Cast is a CAST(x AS type) expression.
type Cast struct {
	X    Expr
	Type string
}

// SQL renders the cast.
func (e *Cast) SQL() string { return "CAST(" + e.X.SQL() + " AS " + e.Type + ")" }

// Between is `x BETWEEN lo AND hi`.
type Between struct {
	X, Lo, Hi Expr
	Not       bool
}

// SQL renders the comparison.
func (e *Between) SQL() string {
	op := " BETWEEN "
	if e.Not {
		op = " NOT BETWEEN "
	}
	return e.X.SQL() + op + e.Lo.SQL() + " AND " + e.Hi.SQL()
}

// CaseExpr is a CASE ... END expression.
type CaseExpr struct {
	Operand Expr
	Whens   []struct{ When, Then Expr }
	Else    Expr
}

// SQL renders the CASE expression.
func (e *CaseExpr) SQL() string {
	var b strings.Builder
	b.WriteString("CASE")
	if e.Operand != nil {
		b.WriteString(" " + e.Operand.SQL())
	}
	for _, w := range e.Whens {
		b.WriteString(" WHEN " + w.When.SQL() + " THEN " + w.Then.SQL())
	}
