				return nil, err
			}
			if !p.acceptKw("AS") {
				return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
			}
			ty, _, err := p.parseTypeName()
			if err != nil {
				return nil, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, err
			}
			return &Cast{X: x, Type: ty}, nil
		case "CASE":
			return p.parseCase()
		case "EXISTS", "SELECT":
			return nil, fmt.Errorf("subqueries are not supported")
		}
	}
	if t.kind == tkIdent || t.kind == tkKeyword {
		p.next()
		name := t.text
		quoted := t.raw
		if p.acceptPunct(".") {
			n2, err := p.name()
			if err != nil {
				return nil, err
			}
			return &ColRef{Table: name, Name: n2, Quoted: n2}, nil
		}
		if p.peek().kind == tkPunct && p.peek().text == "(" {
			p.next()
			call := &Call{Name: name}
			if p.acceptPunct("*") {
				call.Star = true
				if err := p.expectPunct(")"); err != nil {
					return nil, err
				}
				return call, nil
			}
			if p.acceptKw("DISTINCT") {
				call.Distinct = true
			}
			if !p.acceptPunct(")") {
				for {
					a, err := p.parseExpr()
					if err != nil {
						return nil, err
					}
					call.Args = append(call.Args, a)
					if !p.acceptPunct(",") {
						break
					}
				}
				if err := p.expectPunct(")"); err != nil {
					return nil, err
				}
			}
			return call, nil
		}
		return &ColRef{Name: name, Quoted: quoted}, nil
	}
	return nil, fmt.Errorf(`near "%s": syntax error`, t.raw)
}

func (p *sqlParser) parseCase() (Expr, error) {
	p.next() // CASE
	e := &CaseExpr{}
	if !(p.peek().kind == tkKeyword && p.peek().text == "WHEN") {
		x, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		e.Operand = x
	}
	for p.acceptKw("WHEN") {
		w, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if !p.acceptKw("THEN") {
			return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
		}
		t, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		e.Whens = append(e.Whens, struct{ When, Then Expr }{w, t})
	}
	if p.acceptKw("ELSE") {
		x, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		e.Else = x
	}
	if !p.acceptKw("END") {
		return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
	}
	return e, nil
}

func hexBytes(s string) []byte {
	out := make([]byte, 0, len(s)/2)
	for i := 0; i+1 < len(s); i += 2 {
		out = append(out, hexVal(s[i])<<4|hexVal(s[i+1]))
	}
	return out
}

func hexVal(c byte) byte {
	switch {
	case c >= '0' && c <= '9':
		return c - '0'
	case c >= 'a' && c <= 'f':
		return c - 'a' + 10
	case c >= 'A' && c <= 'F':
		return c - 'A' + 10
	}
	return 0
}

