package sqlite

import (
	"fmt"
	"strings"
)

// Stmt is a parsed SQL statement.
type Stmt interface{ stmt() }

// CreateTable is a CREATE TABLE statement.
type CreateTable struct {
	Name        string
	IfNotExists bool
	Temp        bool
	Columns     []*ColumnDef
	Constraints []*TableConstraint
	WithoutRow  bool
	Strict      bool
	Raw         string
}

func (*CreateTable) stmt() {}

// ColumnDef is one column of a CREATE TABLE.
type ColumnDef struct {
	Name          string
	Type          string // as written, e.g. "varchar(255)"
	TypeName      string // "varchar"
	TypeArgs      []string
	NotNull       bool
	PrimaryKey    bool
	PKDesc        bool
	AutoIncrement bool
	Unique        bool
	Default       Expr
	Collate       string
	Checks        []*TableConstraint
	FK            *ForeignKey
	Generated     Expr
	GenStored     bool
	PKName        string
	UniqueName    string
}

// ConstraintKind enumerates table level constraints.
type ConstraintKind int

// The supported constraint kinds.
const (
	ConstraintPK ConstraintKind = iota
	ConstraintUnique
	ConstraintCheck
	ConstraintFK
)

// TableConstraint is a table level constraint.
type TableConstraint struct {
	Name    string
	Kind    ConstraintKind
	Columns []IndexedColumn
	Check   Expr
	FK      *ForeignKey
}

// IndexedColumn is one element of an index or key definition.
type IndexedColumn struct {
	Name    string
	Expr    Expr
	Desc    bool
	Collate string
}

// ForeignKey describes a REFERENCES clause.
type ForeignKey struct {
	Columns   []string
	Table     string
	RefCols   []string
	OnDelete  string
	OnUpdate  string
	Deferred  bool
	MatchFull string
}

// CreateIndex is a CREATE INDEX statement.
type CreateIndex struct {
	Name        string
	Table       string
	Unique      bool
	IfNotExists bool
	Columns     []IndexedColumn
	Where       Expr
	Raw         string
}

func (*CreateIndex) stmt() {}

// DropTable is a DROP TABLE statement.
type DropTable struct {
	Name     string
	IfExists bool
}

func (*DropTable) stmt() {}

// DropIndex is a DROP INDEX statement.
type DropIndex struct {
	Name     string
	IfExists bool
}

func (*DropIndex) stmt() {}

// AlterTable is an ALTER TABLE statement.
type AlterTable struct {
	Name string
	// Exactly one of the following is set.
	RenameTo   string
	RenameCol  [2]string
	AddColumn  *ColumnDef
	DropColumn string
}

func (*AlterTable) stmt() {}

// Insert is an INSERT statement.
type Insert struct {
	Table   string
	Columns []string
	Rows    [][]Expr
	Select  *Select
	Replace bool
}

func (*Insert) stmt() {}

// Select is a (very small) SELECT statement.
type Select struct {
	Columns  []SelectCol
	From     string
	Where    Expr
	OrderBy  []IndexedColumn
	Limit    Expr
	Distinct bool
}

func (*Select) stmt() {}

// SelectCol is one item of a select list.
type SelectCol struct {
	Expr  Expr
	Alias string
	Star  bool
}

// Update is an UPDATE statement.
type Update struct {
	Table string
	Set   []struct {
		Column string
		Value  Expr
	}
	Where Expr
}

func (*Update) stmt() {}

// Delete is a DELETE statement.
type Delete struct {
	Table string
	Where Expr
}

func (*Delete) stmt() {}

// Pragma is a PRAGMA statement.
type Pragma struct {
	Name  string
	Value string
	Arg   string
}

func (*Pragma) stmt() {}

// Transaction is BEGIN, COMMIT or ROLLBACK.
type Transaction struct{ Kind string }

func (*Transaction) stmt() {}

// Noop is a statement that is accepted and ignored.
type Noop struct{ Raw string }

func (*Noop) stmt() {}

// ParseStmt parses a single SQL statement.
func ParseStmt(s string) (Stmt, error) {
	p, err := newSQLParser(s)
	if err != nil {
		return nil, err
	}
	st, err := p.parseStmt(strings.TrimSpace(s))
	if err != nil {
		return nil, err
	}
	return st, nil
}

func (p *sqlParser) parseStmt(raw string) (Stmt, error) {
	switch t := p.peek(); {
	case t.kind != tkKeyword:
		return nil, fmt.Errorf(`near "%s": syntax error`, t.raw)
	case t.text == "CREATE":
		return p.parseCreate(raw)
	case t.text == "DROP":
		return p.parseDrop()
	case t.text == "ALTER":
		return p.parseAlter()
	case t.text == "INSERT" || t.text == "REPLACE":
		return p.parseInsert()
	case t.text == "SELECT":
		return p.parseSelect()
	case t.text == "UPDATE":
		return p.parseUpdate()
	case t.text == "DELETE":
		return p.parseDelete()
	case t.text == "PRAGMA":
		return p.parsePragma()
	case t.text == "BEGIN":
		p.next()
		return &Transaction{Kind: "BEGIN"}, nil
	case t.text == "COMMIT" || t.text == "END":
		p.next()
		return &Transaction{Kind: "COMMIT"}, nil
	case t.text == "ROLLBACK":
		p.next()
		return &Transaction{Kind: "ROLLBACK"}, nil
	case t.text == "SAVEPOINT" || t.text == "RELEASE" || t.text == "ANALYZE" ||
		t.text == "VACUUM" || t.text == "REINDEX" || t.text == "ATTACH" || t.text == "DETACH":
		return &Noop{Raw: raw}, nil
	default:
		return nil, fmt.Errorf(`near "%s": syntax error`, t.raw)
	}
}

func (p *sqlParser) parseCreate(raw string) (Stmt, error) {
	p.next() // CREATE
	temp := p.acceptKw("TEMP") || p.acceptKw("TEMPORARY")
	switch {
	case p.acceptKw("TABLE"):
		return p.parseCreateTable(raw, temp)
	case p.acceptKw("UNIQUE", "INDEX"):
		return p.parseCreateIndex(raw, true)
	case p.acceptKw("INDEX"):
		return p.parseCreateIndex(raw, false)
	case p.acceptKw("VIEW"), p.acceptKw("TRIGGER"), p.acceptKw("VIRTUAL", "TABLE"):
		return &Noop{Raw: raw}, nil
	}
	return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
}

func (p *sqlParser) parseCreateTable(raw string, temp bool) (Stmt, error) {
	ct := &CreateTable{Temp: temp, Raw: raw}
	ct.IfNotExists = p.acceptKw("IF", "NOT", "EXISTS")
	name, err := p.qualifiedName()
	if err != nil {
		return nil, err
	}
	ct.Name = name
	if p.acceptKw("AS") {
		return &Noop{Raw: raw}, nil
	}
	if err := p.expectPunct("("); err != nil {
		return nil, err
	}
	for {
		if c, ok := p.tableConstraintAhead(); ok {
			tc, err := p.parseTableConstraint(c)
			if err != nil {
				return nil, err
			}
			ct.Constraints = append(ct.Constraints, tc)
		} else {
			col, err := p.parseColumnDef()
			if err != nil {
				return nil, err
			}
			ct.Columns = append(ct.Columns, col)
		}
		if !p.acceptPunct(",") {
			break
		}
	}
	if err := p.expectPunct(")"); err != nil {
		return nil, err
	}
	for {
		switch {
		case p.acceptKw("WITHOUT", "ROWID"):
			ct.WithoutRow = true
		case p.acceptKw("STRICT"):
			ct.Strict = true
		default:
			if p.acceptPunct(",") {
				continue
			}
			return ct, nil
		}
	}
}

// tableConstraintAhead reports whether the next tokens start a table constraint.
func (p *sqlParser) tableConstraintAhead() (string, bool) {
	save := p.i
	if p.acceptKw("CONSTRAINT") {
		p.i = save
		return "CONSTRAINT", true
	}
	if t := p.peek(); t.kind == tkKeyword {
		switch t.text {
		case "PRIMARY", "UNIQUE", "CHECK", "FOREIGN":
			return t.text, true
		}
	}
	return "", false
}

func (p *sqlParser) parseTableConstraint(kind string) (*TableConstraint, error) {
	tc := &TableConstraint{}
	if p.acceptKw("CONSTRAINT") {
		n, err := p.name()
		if err != nil {
			return nil, err
		}
		tc.Name = n
	}
	switch {
	case p.acceptKw("PRIMARY", "KEY"):
		tc.Kind = ConstraintPK
		cols, err := p.parseIndexedColumns()
		if err != nil {
			return nil, err
		}
		tc.Columns = cols
		p.parseConflictClause()
	case p.acceptKw("UNIQUE"):
		tc.Kind = ConstraintUnique
		cols, err := p.parseIndexedColumns()
		if err != nil {
			return nil, err
		}
		tc.Columns = cols
		p.parseConflictClause()
	case p.acceptKw("CHECK"):
		tc.Kind = ConstraintCheck
		if err := p.expectPunct("("); err != nil {
			return nil, err
		}
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if err := p.expectPunct(")"); err != nil {
			return nil, err
		}
		tc.Check = e
	case p.acceptKw("FOREIGN", "KEY"):
		tc.Kind = ConstraintFK
		cols, err := p.parseNameList()
		if err != nil {
			return nil, err
		}
		fk, err := p.parseReferences()
		if err != nil {
			return nil, err
		}
		fk.Columns = cols
		tc.FK = fk
	default:
		return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
	}
	return tc, nil
}

func (p *sqlParser) parseNameList() ([]string, error) {
	if err := p.expectPunct("("); err != nil {
		return nil, err
	}
	var out []string
	for {
		n, err := p.name()
		if err != nil {
			return nil, err
		}
		out = append(out, n)
		if !p.acceptPunct(",") {
			break
		}
	}
	return out, p.expectPunct(")")
}

func (p *sqlParser) parseIndexedColumns() ([]IndexedColumn, error) {
	if err := p.expectPunct("("); err != nil {
		return nil, err
	}
	var out []IndexedColumn
	for {
		ic := IndexedColumn{}
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if ref, ok := e.(*ColRef); ok && ref.Table == "" {
			ic.Name = ref.Name
		} else {
			ic.Expr = e
		}
		if p.acceptKw("COLLATE") {
			c, err := p.name()
			if err != nil {
				return nil, err
			}
			ic.Collate = c
		}
		switch {
		case p.acceptKw("ASC"):
		case p.acceptKw("DESC"):
			ic.Desc = true
		}
		out = append(out, ic)
		if !p.acceptPunct(",") {
			break
		}
	}
	return out, p.expectPunct(")")
}

func (p *sqlParser) parseConflictClause() {
	if p.acceptKw("ON", "CONFLICT") {
		p.next()
	}
}

func (p *sqlParser) parseColumnDef() (*ColumnDef, error) {
	name, err := p.name()
	if err != nil {
		return nil, err
	}
	col := &ColumnDef{Name: name}
	if typeAhead(p) {
		t, args, err := p.parseTypeName()
		if err != nil {
			return nil, err
		}
		col.Type = t
		col.TypeArgs = args
		col.TypeName = t
		if i := strings.IndexByte(t, '('); i > 0 {
			col.TypeName = strings.TrimSpace(t[:i])
		}
	}
	for {
		var cname string
		if p.acceptKw("CONSTRAINT") {
			n, err := p.name()
			if err != nil {
				return nil, err
			}
			cname = n
		}
		switch {
		case p.acceptKw("PRIMARY", "KEY"):
			col.PrimaryKey = true
			col.PKName = cname
			switch {
			case p.acceptKw("ASC"):
			case p.acceptKw("DESC"):
				col.PKDesc = true
			}
			p.parseConflictClause()
			if p.acceptKw("AUTOINCREMENT") {
				col.AutoIncrement = true
			}
		case p.acceptKw("NOT", "NULL"):
			col.NotNull = true
			p.parseConflictClause()
		case p.acceptKw("NULL"):
			p.parseConflictClause()
		case p.acceptKw("UNIQUE"):
			col.Unique = true
			col.UniqueName = cname
			p.parseConflictClause()
		case p.acceptKw("CHECK"):
			if err := p.expectPunct("("); err != nil {
				return nil, err
			}
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, err
			}
			col.Checks = append(col.Checks, &TableConstraint{Name: cname, Kind: ConstraintCheck, Check: e})
		case p.acceptKw("DEFAULT"):
			e, err := p.parseDefaultValue()
			if err != nil {
				return nil, err
			}
			col.Default = e
		case p.acceptKw("COLLATE"):
			n, err := p.name()
			if err != nil {
				return nil, err
			}
			col.Collate = n
		case p.acceptKw("REFERENCES"):
			p.i-- // let parseReferences consume the keyword
			fk, err := p.parseReferences()
			if err != nil {
				return nil, err
			}
			fk.Columns = []string{col.Name}
			col.FK = fk
		case p.acceptKw("GENERATED", "ALWAYS", "AS"), p.acceptKw("AS"):
			if err := p.expectPunct("("); err != nil {
				return nil, err
			}
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, err
			}
			col.Generated = e
			switch {
			case p.acceptKw("STORED"):
				col.GenStored = true
			case p.acceptKw("VIRTUAL"):
			}
		default:
			return col, nil
		}
	}
}

// typeAhead reports whether a column type name follows.
func typeAhead(p *sqlParser) bool {
	t := p.peek()
	if t.kind == tkIdent {
		return true
	}
	if t.kind != tkKeyword {
		return false
	}
	switch t.text {
	case "PRIMARY", "NOT", "NULL", "UNIQUE", "CHECK", "DEFAULT", "COLLATE", "REFERENCES",
		"GENERATED", "AS", "CONSTRAINT":
		return false
	}
	return true
}

func (p *sqlParser) parseTypeName() (string, []string, error) {
	var parts []string
	for {
		t := p.peek()
		if t.kind != tkIdent && t.kind != tkKeyword {
			break
		}
		switch t.text {
		case "PRIMARY", "NOT", "NULL", "UNIQUE", "CHECK", "DEFAULT", "COLLATE", "REFERENCES",
			"GENERATED", "AS", "CONSTRAINT":
			goto done
		}
		p.next()
		parts = append(parts, t.raw)
	}
done:
	name := strings.Join(parts, " ")
	var args []string
	if p.acceptPunct("(") {
		for {
			t := p.next()
			args = append(args, t.raw)
			if !p.acceptPunct(",") {
				break
			}
		}
		if err := p.expectPunct(")"); err != nil {
			return "", nil, err
		}
		name += "(" + strings.Join(args, ",") + ")"
	}
	return name, args, nil
}

func (p *sqlParser) parseDefaultValue() (Expr, error) {
	if p.peek().kind == tkPunct && p.peek().text == "(" {
		p.next()
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		if err := p.expectPunct(")"); err != nil {
			return nil, err
		}
		return &Paren{X: e}, nil
	}
	if p.peek().kind == tkPunct && (p.peek().text == "-" || p.peek().text == "+") {
		return p.parseUnaryExpr()
	}
	return p.parsePrimaryExpr()
}

func (p *sqlParser) parseReferences() (*ForeignKey, error) {
	if !p.acceptKw("REFERENCES") {
		return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
	}
	fk := &ForeignKey{}
	n, err := p.qualifiedName()
	if err != nil {
		return nil, err
	}
	fk.Table = n
	if p.peek().kind == tkPunct && p.peek().text == "(" {
		cols, err := p.parseNameList()
		if err != nil {
			return nil, err
		}
		fk.RefCols = cols
	}
	for {
		switch {
		case p.acceptKw("ON", "DELETE"):
			fk.OnDelete = p.parseRefAction()
		case p.acceptKw("ON", "UPDATE"):
			fk.OnUpdate = p.parseRefAction()
		case p.acceptKw("MATCH"):
			n, err := p.name()
			if err != nil {
				return nil, err
			}
			fk.MatchFull = n
		case p.acceptKw("NOT", "DEFERRABLE"), p.acceptKw("DEFERRABLE"):
			switch {
			case p.acceptKw("INITIALLY", "DEFERRED"):
				fk.Deferred = true
			case p.acceptKw("INITIALLY", "IMMEDIATE"):
			}
		default:
			return fk, nil
		}
	}
}

func (p *sqlParser) parseRefAction() string {
	switch {
	case p.acceptKw("SET", "NULL"):
		return "SET NULL"
	case p.acceptKw("SET", "DEFAULT"):
		return "SET DEFAULT"
	case p.acceptKw("CASCADE"):
		return "CASCADE"
	case p.acceptKw("RESTRICT"):
		return "RESTRICT"
	case p.acceptKw("NO", "ACTION"):
		return "NO ACTION"
	}
	return ""
}

func (p *sqlParser) parseCreateIndex(raw string, unique bool) (Stmt, error) {
	ci := &CreateIndex{Unique: unique, Raw: raw}
	ci.IfNotExists = p.acceptKw("IF", "NOT", "EXISTS")
	n, err := p.qualifiedName()
	if err != nil {
		return nil, err
	}
	ci.Name = n
	if !p.acceptKw("ON") {
		return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
	}
	t, err := p.name()
	if err != nil {
		return nil, err
	}
	ci.Table = t
	cols, err := p.parseIndexedColumns()
	if err != nil {
		return nil, err
	}
	ci.Columns = cols
	if p.acceptKw("WHERE") {
		w, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		ci.Where = w
	}
	return ci, nil
}

func (p *sqlParser) parseDrop() (Stmt, error) {
	p.next()
	switch {
	case p.acceptKw("TABLE"):
		ex := p.acceptKw("IF", "EXISTS")
		n, err := p.qualifiedName()
		if err != nil {
			return nil, err
		}
		return &DropTable{Name: n, IfExists: ex}, nil
	case p.acceptKw("INDEX"):
		ex := p.acceptKw("IF", "EXISTS")
		n, err := p.qualifiedName()
		if err != nil {
			return nil, err
		}
		return &DropIndex{Name: n, IfExists: ex}, nil
	case p.acceptKw("VIEW"), p.acceptKw("TRIGGER"):
		return &Noop{}, nil
	}
	return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
}

func (p *sqlParser) parseAlter() (Stmt, error) {
	p.next()
	if !p.acceptKw("TABLE") {
		return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
	}
	n, err := p.qualifiedName()
	if err != nil {
		return nil, err
	}
	at := &AlterTable{Name: n}
	switch {
	case p.acceptKw("RENAME", "TO"):
		to, err := p.name()
		if err != nil {
			return nil, err
		}
		at.RenameTo = to
	case p.acceptKw("RENAME", "COLUMN"), p.acceptKw("RENAME"):
		from, err := p.name()
		if err != nil {
			return nil, err
		}
		if !p.acceptKw("TO") {
			return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
		}
		to, err := p.name()
		if err != nil {
			return nil, err
		}
		at.RenameCol = [2]string{from, to}
	case p.acceptKw("ADD", "COLUMN"), p.acceptKw("ADD"):
		col, err := p.parseColumnDef()
		if err != nil {
			return nil, err
		}
		at.AddColumn = col
	case p.acceptKw("DROP", "COLUMN"), p.acceptKw("DROP"):
		c, err := p.name()
		if err != nil {
			return nil, err
		}
		at.DropColumn = c
	default:
		return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
	}
	return at, nil
}

func (p *sqlParser) parseInsert() (Stmt, error) {
	replace := p.peek().text == "REPLACE"
	p.next()
	if p.acceptKw("OR") {
		p.next()
	}
	p.acceptKw("INTO")
	n, err := p.qualifiedName()
	if err != nil {
		return nil, err
	}
	ins := &Insert{Table: n, Replace: replace}
	if p.peek().kind == tkPunct && p.peek().text == "(" {
		cols, err := p.parseNameList()
		if err != nil {
			return nil, err
		}
		ins.Columns = cols
	}
	switch {
	case p.acceptKw("VALUES"):
		for {
			if err := p.expectPunct("("); err != nil {
				return nil, err
			}
			var row []Expr
			for {
				e, err := p.parseExpr()
				if err != nil {
					return nil, err
				}
				row = append(row, e)
				if !p.acceptPunct(",") {
					break
				}
			}
			if err := p.expectPunct(")"); err != nil {
				return nil, err
			}
			ins.Rows = append(ins.Rows, row)
			if !p.acceptPunct(",") {
				break
			}
		}
	case p.peek().kind == tkKeyword && p.peek().text == "SELECT":
		sel, err := p.parseSelect()
		if err != nil {
			return nil, err
		}
		ins.Select = sel.(*Select)
	case p.acceptKw("DEFAULT", "VALUES"):
		ins.Rows = append(ins.Rows, nil)
	default:
		return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
	}
	// Ignore any upsert clause.
	for !p.eof() {
		p.next()
	}
	return ins, nil
}

func (p *sqlParser) parseSelect() (Stmt, error) {
	p.next()
	sel := &Select{}
	sel.Distinct = p.acceptKw("DISTINCT")
	p.acceptKw("ALL")
	for {
		if p.acceptPunct("*") {
			sel.Columns = append(sel.Columns, SelectCol{Star: true})
		} else {
			e, err := p.parseExpr()
			if err != nil {
				return nil, err
			}
			c := SelectCol{Expr: e}
			if p.acceptKw("AS") {
				a, err := p.name()
				if err != nil {
					return nil, err
				}
				c.Alias = a
			} else if t := p.peek(); t.kind == tkIdent {
				p.next()
				c.Alias = t.text
			}
			sel.Columns = append(sel.Columns, c)
		}
		if !p.acceptPunct(",") {
			break
		}
	}
	if p.acceptKw("FROM") {
		n, err := p.qualifiedName()
		if err != nil {
			return nil, err
		}
		sel.From = n
		if p.acceptKw("AS") {
			if _, err := p.name(); err != nil {
				return nil, err
			}
		} else if t := p.peek(); t.kind == tkIdent {
			p.next()
		}
	}
	if p.acceptKw("WHERE") {
		w, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		sel.Where = w
	}
	if p.acceptKw("ORDER", "BY") {
		cols, err := p.parseOrderBy()
		if err != nil {
			return nil, err
		}
		sel.OrderBy = cols
	}
	if p.acceptKw("LIMIT") {
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		sel.Limit = e
	}
	return sel, nil
}

func (p *sqlParser) parseOrderBy() ([]IndexedColumn, error) {
	var out []IndexedColumn
	for {
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		ic := IndexedColumn{Expr: e}
		if ref, ok := e.(*ColRef); ok {
			ic.Name = ref.Name
		}
		switch {
		case p.acceptKw("ASC"):
		case p.acceptKw("DESC"):
			ic.Desc = true
		}
		out = append(out, ic)
		if !p.acceptPunct(",") {
			return out, nil
		}
	}
}

func (p *sqlParser) parseUpdate() (Stmt, error) {
	p.next()
	n, err := p.qualifiedName()
	if err != nil {
		return nil, err
	}
	up := &Update{Table: n}
	if !p.acceptKw("SET") {
		return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
	}
	for {
		c, err := p.name()
		if err != nil {
			return nil, err
		}
		if !p.acceptPunct("=") {
			return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
		}
		e, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		up.Set = append(up.Set, struct {
			Column string
			Value  Expr
		}{c, e})
		if !p.acceptPunct(",") {
			break
		}
	}
	if p.acceptKw("WHERE") {
		w, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		up.Where = w
	}
	return up, nil
}

func (p *sqlParser) parseDelete() (Stmt, error) {
	p.next()
	if !p.acceptKw("FROM") {
		return nil, fmt.Errorf(`near "%s": syntax error`, p.peek().raw)
	}
	n, err := p.qualifiedName()
	if err != nil {
		return nil, err
	}
	del := &Delete{Table: n}
	if p.acceptKw("WHERE") {
		w, err := p.parseExpr()
		if err != nil {
			return nil, err
		}
		del.Where = w
	}
	return del, nil
}

func (p *sqlParser) parsePragma() (Stmt, error) {
	p.next()
	n, err := p.qualifiedName()
	if err != nil {
		return nil, err
	}
	pr := &Pragma{Name: strings.ToLower(n)}
	switch {
	case p.acceptPunct("="):
		pr.Value = p.next().text
	case p.acceptPunct("("):
		pr.Arg = p.next().text
		if err := p.expectPunct(")"); err != nil {
			return nil, err
		}
	}
	return pr, nil
}

