package sqlite

import (
	"encoding/binary"
	"fmt"
	"os"
	"sort"
	"strings"
)

// object is one row of the sqlite_master table.
type object struct {
	Typ     string // "table", "index", "view" or "trigger"
	Name    string
	TblName string
	SQL     string
	root    int
}

// table is a materialised rowid table.
type table struct {
	obj     *object
	def     *CreateTable
	rows    []*row
	nextRID int64
	// rowidCol is the index of the INTEGER PRIMARY KEY column, or -1.
	rowidCol int
}

// row is a single stored record.
type row struct {
	id   int64
	vals []Value
}

// indexDef is an index maintained by the engine.
type indexDef struct {
	obj    *object
	def    *CreateIndex
	auto   bool
	table  string
	cols   []IndexedColumn
	unique bool
}

// DB is an open SQLite database.
type DB struct {
	path     string
	memory   bool
	pageSize int
	cookie   uint32
	objects  []*object
	tables   map[string]*table
