	}
	if len(a) < len(b) {
		return -1
	}
	return 0
}

func storageClass(v Value) int {
	switch v.Kind {
	case KindNull:
		return 0
	case KindInt, KindFloat:
		return 1
	case KindText:
		return 2
	default:
		return 3
	}
}

func compareValues(a, b Value) int {
	ca, cb := storageClass(a), storageClass(b)
	if ca != cb {
		if ca < cb {
			return -1
		}
		return 1
	}
	switch ca {
	case 0:
		return 0
	case 1:
		x, y := numOf(a), numOf(b)
		switch {
		case x < y:
			return -1
		case x > y:
			return 1
		}
		return 0
	case 2:
		return strings.Compare(a.Str, b.Str)
	default:
		return strings.Compare(string(a.Blob), string(b.Blob))
	}
}

func numOf(v Value) float64 {
	if v.Kind == KindInt {
		return float64(v.Int)
	}
	return v.Real
}
